  'The form data is incomplete. Perhaps you need to increase max_input_vars on your server?' => 'Ձևի տվյալները թերի են: Միգուցե դուք պետք է մեծացնեք max_input_vars-ը ձեր սերվերում?',
  'This form has expired. Try again.' => 'Այս ձևի ժամկետը լրացել է: Նորից փորձեք:',
