  'Custom GEDCOM tags are discouraged. Try to use only standard GEDCOM tags.' => 'Հատուկ GEDCOM պիտակները չեն խրախուսվում: Փորձեք օգտագործել միայն ստանդարտ GEDCOM թեգերը:',
  'Invalid GEDCOM tag.' => 'Անվավեր GEDCOM թեգ:',
