  'webtrees cannot create thumbnails for this file format.' => 'webtrees-ը չի կարող այս ֆայլի ձևաչափի մանրապատկերներ ստեղծել:',
  'This filename is not compatible with the GEDZIP file format.' => 'Այս ֆայլի անունը համատեղելի չէ GEDZIP ֆայլի ձևաչափի հետ:',
