  'You are not allowed to send messages that contain external links.' => 'Ձեզ չի թույլատրվում ուղարկել արտաքին հղումներ պարունակող հաղորդագրություններ:',
  'You should delete the “%1$s” from “%2$s” and try again.' => 'Դուք պետք է ջնջեք «%1$s»-ը «%2$s»-ից և նորից փորձեք:',
  'The message was not sent.' => 'Հաղորդագրությունը չի ուղարկվել։',
