  'You need to be a family member to access this website.' => 'Այս կայք մուտք գործելու համար դուք պետք է ընտանիքի անդամ լինեք:',
  'You can apply for an account using the link below.' => 'Դուք կարող եք դիմել ստորև նշված հղման միջոցով:',
