  '%s family has been updated.' . "\0" . '%s families have been updated.' => '%s ընտանիքը թարմացվել է:' . "\0" . '%s ընտանիքներ թարմացվել է:',
  '%s repository has been updated.' . "\0" . '%s repositories have been updated.' => '%s պահոցը թարմացվել է:' . "\0" . '%s պահոցները թարմացվել են:',
  '%s source has been updated.' . "\0" . '%s sources have been updated.' => '%s աղբյուրը թարմացվել է:' . "\0" . '%s աղբյուրները թարմացվել են:',
  '%s note has been updated.' . "\0" . '%s notes have been updated.' => '%s նշումը թարմացվել է:' . "\0" . '%s նշումները թարմացվել են:',
  'Search and replace' => 'Որոնել և փոխարինել',
  'The family tree “%s” will be shown to visitors when they first arrive at this website.' => '«%s» տոհմածառը կցուցադրվի այցելուներին, երբ նրանք առաջին անգամ գան այս կայք:',
  'Oops! webtrees was unable to create files in this folder.' => 'Վա՜յ webtrees-ը չկարողացավ ֆայլեր ստեղծել այս թղթապանակում:',
  'This usually means that you need to change the folder permissions to 777.' => 'Սա սովորաբար նշանակում է, որ դուք պետք է փոխեք թղթապանակի թույլտվությունները 777-ի:',
  'You must enter all the administrator account fields.' => 'Դուք պետք է մուտքագրեք ադմինիստրատորի հաշվի բոլոր դաշտերը:',
  'The password needs to be at least six characters long.' => 'Գաղտնաբառը պետք է լինի առնվազն վեց նիշ:',
  'Website logs' => 'Կայքի տեղեկամատյաններ',
  'Cannot write to the folder “%s”.' => 'Հնարավոր չէ գրել «%s» թղթապանակում:',
  'The folder “%s” does not exist.' => '«%s» պանակը գոյություն չունի:',
  'Website preferences' => 'Կայքի նախապատվությունները',
  'Sign-in and registration' => 'Մուտք և գրանցում',
  'No predefined text' => 'Նախապես սահմանված տեքստ չկա',
  'Predefined text that states all users can request a user account' => 'Նախապես սահմանված տեքստ, որը նշում է, որ բոլոր օգտվողները կարող են պահանջել օգտվողի հաշիվ',
  'Predefined text that states admin will decide on each request for a user account' => 'Նախապես սահմանված տեքստ, որը նշում է, որ ադմինիստրատորը կորոշի օգտվողի հաշվի յուրաքանչյուր հարցում',
  'Predefined text that states only family members can request a user account' => 'Նախապես սահմանված տեքստ, որը նշում է, որ միայն ընտանիքի անդամները կարող են օգտատիրոջ հաշիվ պահանջել',
  'Choose user defined welcome text typed below' => 'Ընտրեք օգտվողի կողմից սահմանված ողջույնի տեքստը, որը մուտքագրված է ստորև',
  'GEDCOM tags' => 'GEDCOM պիտակներ',
  'The GEDCOM file “%s” has been imported.' => 'GEDCOM «%s» ֆայլը ներմուծվել է:',
  'Preferences' => 'Նախապատվություններ',
  'Set the default blocks for new family trees' => 'Սահմանեք լռելյայն բլոկները նոր տոհմածառերի համար',
  'Change the “Home page” blocks' => 'Փոխեք «Գլխավոր էջի» բլոկները',
