  'A report of individuals who died in a given time or place.' => 'Հաշվետվություն անհատների մասին, ովքեր մահացել են տվյալ պահին կամ վայրում:',
  'A chart of an individual’s descendants.' => 'Անհատի ժառանգների աղյուսակ.',
  'Descendants of %s' => '%s-ի ժառանգներ',
  'A sidebar showing the descendants of an individual.' => 'Կողային գոտի, որը ցույց է տալիս անհատի հետնորդները:',
  'A report of an individual’s descendants, in a narrative style.' => 'Զեկույց անհատի ժառանգների մասին՝ պատմողական ոճով։',
  'Esri/ArcGIS' => 'Esri/ArcGIS',
