  'A report of the information provided by a source.' => 'Տեղեկատվության հաղորդումը աղբյուրի կողմից։',
  'Family book' => 'Ընտանեկան գիրք',
  'A chart of an individual’s ancestors and descendants, as a family book.' => 'Անհատի նախնիների և ժառանգների աղյուսակը՝ որպես ընտանեկան գիրք:',
