  'A report of family members and their details.' => 'Ընտանիքի անդամների հաշվետվությունը և նրանց մանրամասները:',
  'A list of families.' => 'Ընտանիքների ցանկ.',
  'Family navigator' => 'Ընտանեկան նավիգատոր',
  'A sidebar showing an individual’s close families and relatives.' => 'Կողային գոտի, որը ցույց է տալիս անհատի մերձավոր ընտանիքներն ու հարազատները:',
  'Favorites' => 'Ֆավորիտներ',
  'Display and manage a family tree’s favorite pages.' => 'Ցուցադրել և կառավարել տոհմածառի սիրելի էջերը:',
  'Family news and site announcements.' => 'Ընտանեկան նորություններ և կայքի հայտարարություններ.',
  'News' => 'Նորություններ',
  'Add/edit a journal/news entry' => 'Ավելացնել/խմբագրել ամսագիր/նորությունների գրառում',
  'Statistics' => 'Վիճակագրություն',
  'The size of the family tree, earliest and latest events, common names, etc.' => 'Տոհմածառի չափը, ամենավաղ և վերջին իրադարձությունները, ընդհանուր անունները և այլն:',
  'Fan chart' => 'Երկրպագուների աղյուսակ',
  'A fan chart of an individual’s ancestors.' => 'Անհատի նախնիների երկրպագուների աղյուսակը:',
  'Fan chart of %s' => '%s-ի երկրպագուների աղյուսակը',
  'half circle' => 'կես շրջան',
  'three-quarter circle' => 'երեք քառորդ շրջան',
  'full circle' => 'ամբողջական շրջան',
  'Convert %s tags to GEDCOM 5.5.1' => 'Փոխարկեք %s պիտակները GEDCOM 5.5.1-ի',
  'Replace cemetery tags with burial places.' => 'Փոխարինեք գերեզմանոցի պիտակները թաղման վայրերով:',
  'Remove duplicate links' => 'Հեռացրեք կրկնօրինակ հղումները',
  'A common error is to have multiple links to the same record, for example listing the same child more than once in a family record.' => 'Ընդհանուր սխալը միևնույն գրառումին մի քանի հղումներ ունենալն է, օրինակ՝ միևնույն երեխային մեկից ավելի անգամ ընտանեկան գրառումներում նշելը:',
  'Add missing death records' => 'Ավելացրեք անհայտ կորած մահվան գրառումները',
  'You can speed up the privacy calculations by adding a death record to individuals whose death can be inferred from other dates, but who do not have a record of death, burial, cremation, etc.' => 'Դուք կարող եք արագացնել գաղտնիության հաշվարկները՝ ավելացնելով մահվան արձանագրություն այն անձանց, որոնց մահը կարելի է եզրակացնել այլ ամսաթվերից, բայց ովքեր չունեն մահվան, հուղարկավորության, դիակիզման և այլնի գրառում:',
  'Fix name slashes and spaces' => 'Ուղղել անունների շեղերը և բացատները',
  'Correct NAME records of the form “John/DOE/” or “John /DOE”, as produced by older genealogy programs.' => '«John/DOE/» կամ «John /DOE» ձևի ԱՆՎԱՆՈՒԹՅԱՆ գրառումները, որոնք արտադրվել են ավելի հին ծագումնաբանական ծրագրերի կողմից:',
  'Some genealogy software stores all names in a single name record, using custom tags such as _MARNM and _AKA. An alternative is to create a new name record for each name.' => 'Որոշ ծագումնաբանական ծրագրեր պահում են բոլոր անունները մեկ անվանման գրառումում՝ օգտագործելով հատուկ պիտակներ, ինչպիսիք են _MARNM և _AKA: Այլընտրանք է յուրաքանչյուր անվան համար ստեղծել նոր անվանական գրառում:',
  'Update place names' => 'Թարմացրեք տեղանունները',
  'Update the higher-level parts of place names, while keeping the lower-level parts.' => 'Թարմացրեք տեղանունների ավելի բարձր մակարդակի մասերը՝ պահպանելով ստորին մակարդակի մասերը:',
  '“Highlighted image” (_PRIM) tags are used by some genealogy applications to indicate the preferred image for an individual. An alternative is to re-order the images so that the preferred one is listed first.' => '«ընդգծված պատկեր» (_PRIM) թեգերն օգտագործվում են որոշ ծագումնաբանական հավելվածների կողմից՝ անհատի համար նախընտրելի պատկերը նշելու համար: Այլընտրանք է պատկերները վերադասավորելն այնպես, որ նախընտրածը առաջինը նշված լինի:',
  'Search and replace text, using simple searches or advanced pattern matching.' => 'Որոնեք և փոխարինեք տեքստը՝ օգտագործելով պարզ որոնումներ կամ առաջադեմ օրինաչափությունների համապատասխանություն:',
  'Match the exact text, even if it occurs in the middle of a word.' => 'Համապատասխանեցրեք ճշգրիտ տեքստը, նույնիսկ եթե այն հայտնվում է բառի մեջտեղում:',
  'Match the exact text, unless it occurs in the middle of a word.' => 'Համապատասխանեցրեք ճշգրիտ տեքստը, եթե այն չի հայտնվում բառի մեջտեղում:',
  'Use a “?” to match a single character, use “*” to match zero or more characters.' => 'Օգտագործեք «?» մեկ նիշին համապատասխանելու համար օգտագործեք «*»՝ զրո կամ ավելի նիշերը համապատասխանելու համար:',
  'Regular expression' => 'Կանոնավոր արտահայտություն',
  'Locations' => 'Վայրեր',
  'Media objects' => 'Մեդիա օբյեկտներ',
  'Notes' => 'Նշումներ',
  'Repositories' => 'Պահեստարաններ',
  'Sources' => 'Աղբյուրներ',
  'Submitters' => 'Ներկայացնողներ',
  '_WT_OBJE_SORT tags were used by old versions of webtrees to indicate the preferred image for an individual. An alternative is to re-order the images so that the preferred one is listed first.' => '_WT_OBJE_SORT թեգերն օգտագործվել են վեբ ծառերի հին տարբերակների կողմից՝ անհատի համար նախընտրելի պատկերը նշելու համար: Այլընտրանք է պատկերները վերադասավորելն այնպես, որ նախընտրածը առաջինը նշված լինի:',
  'FAQ' => 'ՀՏՀ',
