  'Count the visits to each page' => 'Հաշվեք յուրաքանչյուր էջի այցելությունները',
  'This page has been viewed %s time.' . "\0" . 'This page has been viewed %s times.' => 'Այս էջը դիտվել է %s անգամ:' . "\0" . 'Էջերի դիտումների քանակը: %s.',
  'An hourglass chart of an individual’s ancestors and descendants.' => 'Անհատի նախնիների և ժառանգների ավազի ժամացույցի աղյուսակը:',
  'Hourglass chart of %s' => '%s-ի ավազի ժամացույցի գծապատկեր',
  'HTML' => 'HTML',
  'Add your own text and graphics.' => 'Ավելացրեք ձեր սեփական տեքստը և գրաֆիկան:',
