  'Related families' => 'Հարակից ընտանիքներ',
  'A report of the families that are closely related to an individual.' => 'Անհատի հետ սերտ առնչություն ունեցող ընտանիքների հաշվետվություն:',
  'A list of individuals.' => 'Անհատների ցանկ.',
  'Extra information' => 'Լրացուցիչ տեղեկություններ',
  'A sidebar showing non-genealogy information about an individual.' => 'Անհատականի մասին ոչ ծագումնաբանական տեղեկություններ ցուցադրող կողագոտ:',
  'A report of an individual’s details.' => 'Անհատի մանրամասների հաշվետվություն:',
