  'Son of %s' => '%s-ի որդին',
  'Daughter of %s' => '%s-ի դուստրը',
  'Child of %s' => '%s-ի երեխա',
  'An interactive tree, showing all the ancestors and descendants of an individual.' => 'Ինտերակտիվ ծառ, որը ցույց է տալիս անհատի բոլոր նախնիներն ու հետնորդները:',
  'Lifespans' => 'Կյանքի տևողություններ',
  'A chart of individuals’ lifespans.' => 'Անհատների կյանքի տևողության աղյուսակ.',
  '%s individual' . "\0" . '%s individuals' => '%s անհատ' . "\0" . '%s անհատներ',
  'The lists menu.' => 'Ցուցակների մենյու.',
  'A list of locations.' => 'Վայրերի ցանկ:',
  'Who is online' => 'Ով է առցանց',
  'A list of users and visitors who are currently online.' => 'Օգտատերերի և այցելուների ցուցակ, ովքեր ներկայումս առցանց են:',
  'An alternative way to sign in and sign out.' => 'Մուտք գործելու և դուրս գալու այլընտրանքային միջոց:',
  'Sign out' => 'Դուրս գալ',
  'Mapbox' => 'Քարտեզարկղ',
  'Nominatim' => 'անվանական',
  'OpenRouteService' => 'OpenRouteService',
  'OpenStreetMap™' => 'OpenStreetMap™',
  'Marriages' => 'Ամուսնություններ',
  'A report of individuals who were married in a given time or place.' => 'Հաշվետվություն անհատների մասին, ովքեր ամուսնացել են տվյալ պահին կամ վայրում:',
  'Matomo™ / Piwik™ analytics' => 'Matomo™ / Piwik™ վերլուծություն',
  'A list of media objects.' => 'Լրատվամիջոցների օբյեկտների ցանկ.',
  'A tab showing the media objects linked to an individual.' => 'Ներդիր, որը ցույց է տալիս անհատի հետ կապված մեդիա օբյեկտները:',
  'minimal' => 'նվազագույն',
  'Missing data' => 'Տվյալներ բացակայում են',
  'A report of the information that is missing for an individual and their relatives.' => 'Անհատի և նրանց հարազատների համար բացակայող տեղեկությունների հաղորդում:',
  'Add historic events to an individual’s page.' => 'Պատմական իրադարձություններ ավելացրեք անհատի էջին:',
  'Use an external service to find locations.' => 'Օգտագործեք արտաքին ծառայություն՝ վայրեր գտնելու համար:',
  'Map link' => 'Քարտեզի հղում',
  'View this location using %s' => 'Դիտեք այս վայրը՝ օգտագործելով %s-ը',
  'Theme' => 'Թեմա',
  'Family with spouse' => 'Ընտանիք ամուսնու հետ',
  'Customize this page' => 'Անհատականացրեք այս էջը',
  'My individual record' => 'Իմ անհատական ռեկորդը',
  'My pages' => 'Իմ էջերը',
  'My pedigree' => 'Իմ տոհմը',
  'Shared notes' => 'Համօգտագործվող նշումներ',
