  'The search returned too many results.' => 'Որոնումը չափազանց շատ արդյունքներ տվեց:',
  'The PHP extension “%s” is not installed.' => 'PHP «%s» ընդլայնումը տեղադրված չէ:',
  'The PHP.INI setting “%1$s” is disabled.' => 'PHP.INI «%1$s» կարգավորումն անջատված է:',
  'The PHP.INI setting “%1$s” is enabled.' => 'PHP.INI «%1$s» պարամետրը միացված է:',
  'The PHP function “%1$s” is disabled.' => 'PHP «%1$s» ֆունկցիան անջատված է:',
  'Your web server is using PHP version %s, which is no longer receiving security updates. You should upgrade to a later version as soon as possible.' => 'Ձեր վեբ սերվերն օգտագործում է PHP %s տարբերակը, որն այլևս անվտանգության թարմացումներ չի ստանում: Դուք պետք է հնարավորինս շուտ թարմացնեք ավելի ուշ տարբերակի:',
  'SQLite version %s is installed. SQLite version %s or later is required.' => 'Տեղադրված է SQLite %s տարբերակը: Պահանջվում է SQLite %s կամ ավելի նոր տարբերակ:',
