  'The following facts and events were only found in the record of %s.' => 'Հետևյալ փաստերն ու իրադարձությունները հայտնաբերվել են միայն %s -ի գրառումներում:',
  'Preferences exist for the module “%s”, but this module no longer exists.' => 'Նախապատվություններ կան «%s» մոդուլի համար, սակայն այս մոդուլն այլևս գոյություն չունի:',
