  'See %s for more information.' => 'Լրացուցիչ տեղեկությունների համար տե՛ս %s:',
  'webtrees needs to send emails, such as password reminders and website notifications.' => 'webtrees-ը պետք է նամակներ ուղարկի, ինչպիսիք են գաղտնաբառի հիշեցումները և կայքի ծանուցումները:',
  'Sender name' => 'Ուղարկողի անունը',
  'This name is used in the “From” field, when sending automatic emails from this server.' => 'Այս անունը օգտագործվում է «From» դաշտում՝ այս սերվերից ավտոմատ նամակներ ուղարկելիս:',
  'Sender email' => 'Ուղարկողի էլ',
