  'Port number' => 'Նավահանգստի համարը',
  'By default, SMTP works on port 25.' => 'Լռելյայնորեն, SMTP-ն աշխատում է 25-րդ նավահանգստում:',
  'Use password' => 'Օգտագործեք գաղտնաբառը',
  'Most SMTP servers require a password.' => 'SMTP սերվերների մեծ մասը պահանջում է գաղտնաբառ:',
  'Username' => 'Օգտվողի անունը',
  'The username required for authentication with the SMTP server.' => 'SMTP սերվերի հետ նույնականացման համար անհրաժեշտ օգտվողի անունը:',
  'Password' => 'Գաղտնաբառ',
  'show' => 'ցույց տալ',
  'Show password' => 'Ցույց տալ գաղտնաբառը',
  'hide' => 'թաքցնել',
  'Hide password' => 'Թաքցնել գաղտնաբառը',
  'The password required for authentication with the SMTP server.' => 'SMTP սերվերի հետ նույնականացման համար անհրաժեշտ գաղտնաբառը:',
  'Secure connection' => 'Ապահով կապ',
  'Most servers do not use secure connections.' => 'Սերվերների մեծ մասը չի օգտագործում անվտանգ կապեր:',
  'Sending server name' => 'Ուղարկվում է սերվերի անունը',
  'Most mail servers require that the sending server identifies itself correctly, using a valid domain name.' => 'Փոստի սերվերներից շատերը պահանջում են, որ ուղարկող սերվերն իրեն ճիշտ նույնականացնի՝ օգտագործելով վավեր տիրույթի անուն:',
  'Most mail servers require a valid domain name.' => 'Փոստի սերվերներից շատերը պահանջում են վավեր տիրույթի անուն:',
  'DKIM digital signature' => 'DKIM թվային ստորագրություն',
  'Domain name' => 'Դոմենի անուն',
  'Selector' => 'Ընտրիչ',
  'Private key' => 'Անձնական բանալի',
  'Send a test email using these settings' => 'Ուղարկեք փորձնական նամակ՝ օգտագործելով այս կարգավորումները',
  'Data folder' => 'Տվյալների թղթապանակ',
  'This folder will be used by webtrees to store media files, GEDCOM files, temporary files, etc. These files may contain private data, and should not be made available over the internet.' => 'Այս թղթապանակը կօգտագործվի վեբ ծառերի կողմից՝ մեդիա ֆայլեր, GEDCOM ֆայլեր, ժամանակավոր ֆայլեր և այլն պահելու համար: Այս ֆայլերը կարող են պարունակել անձնական տվյալներ և չպետք է հասանելի լինեն ինտերնետի միջոցով:',
  'To protect this private data, webtrees uses an Apache configuration file (.htaccess) which blocks all access to this folder. If your web-server does not support .htaccess files, and you cannot restrict access to this folder, then you can select another folder, away from your web documents.' => 'Այս մասնավոր տվյալները պաշտպանելու համար webtrees-ն օգտագործում է Apache-ի կազմաձևման ֆայլ (.htaccess), որն արգելափակում է այս պանակի բոլոր մուտքը: Եթե ձեր վեբ-սերվերը չի աջակցում .htaccess ֆայլեր, և դուք չեք կարող սահմանափակել մուտքը դեպի այս թղթապանակ, ապա կարող եք ընտրել մեկ այլ թղթապանակ՝ հեռու ձեր վեբ փաստաթղթերից:',
  'If you select a different folder, you must also move all files (except config.ini.php, index.php, and .htaccess) from the existing folder to the new folder.' => 'Եթե ընտրեք մեկ այլ պանակ, դուք պետք է նաև տեղափոխեք բոլոր ֆայլերը (բացի config.ini.php, index.php և .htaccess) առկա պանակից նոր թղթապանակ:',
  'The folder can be specified in full (e.g. /home/user_name/webtrees_data/) or relative to the installation folder (e.g. ../../webtrees_data/).' => 'Թղթապանակը կարելի է ամբողջությամբ նշել (օրինակ՝ /home/user_name/webtrees_data/) կամ հարաբերական լինել տեղադրման թղթապանակին (օրինակ՝ ../../webtrees_data/):',
  'The time zone is required for date calculations, such as knowing today’s date.' => 'Ժամային գոտին պահանջվում է ամսաթվի հաշվարկների համար, օրինակ՝ այսօրվա ամսաթիվը իմանալու համար:',
  'Default theme' => 'Կանխադրված թեմա',
  'You can change the appearance of webtrees using “themes”. Each theme has a different style, layout, color scheme, etc.' => 'Դուք կարող եք փոխել վեբ ծառերի տեսքը՝ օգտագործելով «թեմաներ»: Յուրաքանչյուր թեմա ունի տարբեր ոճ, դասավորություն, գունային սխեման և այլն:',
  'If a visitor to the website has not selected a preferred language in their browser preferences, or they have selected an unsupported language, then this language will be used. Typically this applies to search engines.' => 'Եթե կայքի այցելուն չի ընտրել նախընտրած լեզուն իր դիտարկիչի նախապատվություններում, կամ ընտրել է չաջակցվող լեզու, ապա այս լեզուն կօգտագործվի: Սովորաբար դա վերաբերում է որոնման համակարգերին:',
  'Show list of family trees' => 'Ցույց տալ տոհմածառերի ցանկը',
  'For websites with more than one family tree, this option will show the list of family trees in the main menu, the search pages, etc.' => 'Մեկից ավելի տոհմածառ ունեցող կայքերի համար այս տարբերակը ցույց կտա տոհմածառերի ցանկը հիմնական ցանկում, որոնման էջերը և այլն:',
  'Welcome text on sign-in page' => 'Ողջույնի տեքստ մուտքի էջում',
  'Custom welcome text' => 'Պատվերով ողջույնի տեքստ',
  'To set this text for other languages, you must switch to that language, and visit this page again.' => 'Այս տեքստը այլ լեզուների համար նախադրելու համար դուք պետք է անցնեք այդ լեզվին և նորից այցելեք այս էջը:',
  'Allow visitors to request a new user account' => 'Թույլ տվեք այցելուներին նոր օգտվողի հաշիվ պահանջել',
  'The new user will be asked to confirm their email address before the account is created.' => 'Նոր օգտվողին կպահանջվի հաստատել իր էլփոստի հասցեն՝ նախքան հաշիվը ստեղծելը:',
  'Details of the new user will be sent to the genealogy contact for the corresponding family tree.' => 'Նոր օգտատիրոջ տվյալները կուղարկվեն համապատասխան տոհմածառի կոնտակտներին:',
  'An administrator must approve the new user account and select an access level before the user can sign in.' => 'Ադմինիստրատորը պետք է հաստատի նոր օգտվողի հաշիվը և ընտրի մուտքի մակարդակ, նախքան օգտատերը մուտք գործի:',
  'Show acceptable use agreement on “Request a new user account” page' => 'Ցույց տալ ընդունելի օգտագործման համաձայնագիրը «Պահանջել նոր օգտվողի հաշիվ» էջում',
  'Synchronize family trees with GEDCOM files' => 'Համաժամացրեք տոհմածառերը GEDCOM ֆայլերի հետ',
  'Create, update, and delete a family tree for every GEDCOM file in the data folder.' => 'Ստեղծեք, թարմացրեք և ջնջեք տոհմածառ յուրաքանչյուր GEDCOM ֆայլի համար տվյալների թղթապանակում:',
  'Caution! This may take a long time. Be patient.' => 'զգույշ Սա կարող է երկար ժամանակ տևել: Եղեք համբերատար։',
  'Standard GEDCOM tags' => 'Ստանդարտ GEDCOM պիտակներ',
  'The GEDCOM standard provides a large number of data-entry fields, called tags.' => 'GEDCOM ստանդարտը ապահովում է տվյալների մուտքագրման մեծ թվով դաշտեր, որոնք կոչվում են պիտակներ:',
  'Some of these GEDCOM tags are used infrequently or never used.' => 'Այս GEDCOM պիտակներից մի քանիսը օգտագործվում են հազվադեպ կամ երբեք չեն օգտագործվում:',
  'You can simplify the edit forms by hiding GEDCOM tags that you do not use.' => 'Դուք կարող եք պարզեցնել խմբագրման ձևերը՝ թաքցնելով GEDCOM պիտակները, որոնք դուք չեք օգտագործում:',
  'Names' => 'Անուններ',
  'Hide GEDCOM tags' => 'Թաքցնել GEDCOM պիտակները',
  'Addresses' => 'Հասցեներ',
  'Source citations' => 'Աղբյուրի մեջբերումներ',
  'LDS church' => 'LDS եկեղեցի',
  'Identifiers' => 'Նույնացուցիչներ',
  'GEDCOM 7' => 'GEDCOM 7',
  'The next version of the GEDCOM standard will add new tags and remove old ones. You can use some of the new tags now.' => 'GEDCOM ստանդարտի հաջորդ տարբերակը կավելացնի նոր պիտակներ և կհեռացնի հինները: Այժմ կարող եք օգտագործել որոշ նոր պիտակներ:',
  'Time of birth and time of death' => 'Ծննդյան և մահվան ժամանակը',
  'Family fact' => 'Ընտանեկան փաստ',
  'Many genealogy applications define their own custom GEDCOM tags and webtrees will be able to display most of them.' => 'Շատ ծագումնաբանության հավելվածներ սահմանում են իրենց հատուկ GEDCOM պիտակները, և վեբ ծառերը կկարողանան ցուցադրել դրանց մեծ մասը:',
  'It is not recommended to use custom GEDCOM tags. This data can be lost when you transfer it to other applications.' => 'Խորհուրդ չի տրվում օգտագործել հատուկ GEDCOM պիտակներ: Այս տվյալները կարող են կորչել, երբ դրանք տեղափոխեք այլ հավելվածներ:',
  'To create new data using custom tags, you need to enable them.' => 'Հատուկ պիտակների միջոցով նոր տվյալներ ստեղծելու համար դուք պետք է միացնեք դրանք:',
  'Individual facts and events' => 'Անհատական փաստեր և իրադարձություններ',
  'Family facts and events' => 'Ընտանեկան փաստեր և իրադարձություններ',
  'GEDCOM errors' => 'GEDCOM սխալներ',
  'Hide these errors' => 'Թաքցնել այս սխալները',
  'No errors have been found.' => 'Սխալներ չեն հայտնաբերվել:',
  'show more' => 'ցույց տալ ավելին',
  'Family tree title' => 'Տոհմածառի վերնագիր',
  'Avoid spaces and punctuation. A family name might be a good choice.' => 'Խուսափեք բացատներից և կետադրական նշաններից: Ընտանեկան անունը կարող է լավ ընտրություն լինել:',
  'create' => 'ստեղծել',
  'After creating the family tree, you will be able to import data from a GEDCOM file.' => 'Տոհմածառը ստեղծելուց հետո դուք կկարողանաք տվյալներ ներմուծել GEDCOM ֆայլից:',
  'Merge' => 'Միաձուլել',
  'No duplicates have been found.' => 'Կրկնօրինակներ չեն գտնվել:',
  'Export preferences' => 'Արտահանման նախապատվություններ',
  'This will delete all the genealogy data from “%s” and replace it with data from a GEDCOM file.' => 'Սա կջնջի բոլոր ծագումնաբանական տվյալները «%s»-ից և այն կփոխարինի GEDCOM ֆայլի տվյալներով:',
  'You have selected a GEDCOM file with a different name. Is this correct?' => 'Դուք ընտրել եք GEDCOM ֆայլ այլ անունով: Սա ճի՞շտ է?',
  'Select a GEDCOM file to import' => 'Ներմուծելու համար ընտրեք GEDCOM ֆայլ',
  'No GEDCOM files found.' => 'GEDCOM ֆայլեր չեն գտնվել:',
  'Import preferences' => 'Ներմուծման նախապատվություններ',
  'automatic' => 'ավտոմատ',
  'Keep media objects' => 'Պահպանեք լրատվամիջոցների օբյեկտները',
  'If you have created media objects in webtrees, and have subsequently edited this GEDCOM file using genealogy software that deletes media objects, then select this option to merge the current media objects with the new GEDCOM file.' => 'Եթե դուք ստեղծել եք մեդիա օբյեկտներ վեբ ծառերում և այնուհետև խմբագրել եք այս GEDCOM ֆայլը՝ օգտագործելով ծագումնաբանական ծրագրակազմ, որը ջնջում է մեդիա օբյեկտները, ապա ընտրեք այս տարբերակը՝ ընթացիկ մեդիա օբյեկտները նոր GEDCOM ֆայլի հետ միացնելու համար:',
  'Add spaces where long lines were wrapped' => 'Ավելացնել բացատներ, որտեղ երկար տողեր են փաթաթված',
  'If you created this GEDCOM file using genealogy software that omits spaces when splitting long lines, then select this option to reinsert the missing spaces.' => 'Եթե դուք ստեղծել եք այս GEDCOM ֆայլը՝ օգտագործելով ծագումնաբանական ծրագրակազմ, որը բաց է թողնում երկար տողերը բաժանելիս, ապա ընտրեք այս տարբերակը՝ բացակայող բացերը նորից զետեղելու համար:',
  'Remove the GEDCOM media path from filenames' => 'Հեռացրեք GEDCOM մեդիա ուղին ֆայլերի անուններից',
  'Some genealogy software creates GEDCOM files that contain media filenames with full paths. These paths will not exist on the web-server. To allow webtrees to find the file, the first part of the path must be removed.' => 'Որոշ ծագումնաբանական ծրագրեր ստեղծում են GEDCOM ֆայլեր, որոնք պարունակում են մեդիա ֆայլերի անուններ՝ ամբողջական ուղիներով: Այս ուղիները չեն լինի վեբ-սերվերի վրա: Որպեսզի վեբ ծառերը կարողանան գտնել ֆայլը, ճանապարհի առաջին մասը պետք է հեռացվի:',
  'For example, if the GEDCOM file contains %1$s and webtrees expects to find %2$s in the media folder, then you would need to remove %3$s.' => 'Օրինակ, եթե GEDCOM ֆայլը պարունակում է %1$s, և webtrees-ն ակնկալում է գտնել %2$s մեդիա թղթապանակում, ապա ձեզ հարկավոր է հեռացնել %3$s-ը:',
  'In a family tree, each record has an internal reference number (called an “XREF”) such as “F123” or “R14”.' => 'Տոհմածառում յուրաքանչյուր գրառում ունի ներքին հղման համար (կոչվում է «XREF»), օրինակ՝ «F123» կամ «R14»:',
  'The two family trees have %1$s record which uses the same “XREF”.' . "\0" . 'The two family trees have %1$s records which use the same “XREF”.' => 'Երկու տոհմածառերն ունեն %1$s գրառում, որն օգտագործում է նույն «XREF»-ը:' . "\0" . 'Երկու տոհմածառերն ունեն %1$s գրառումներ, որոնք օգտագործում են նույն «XREF»-ը:',
  'You must renumber the records in one of the trees before you can merge them.' => 'Դուք պետք է վերահամարակալեք ծառերից մեկի գրառումները, նախքան դրանք միաձուլեք:',
  'Copy all the records from %1$s into %2$s.' => 'Պատճենեք բոլոր գրառումները %1$s-ից %2$s:',
  'General' => 'Գեներալ',
  'This individual will be selected by default when viewing charts and reports.' => 'Այս անհատը կընտրվի լռելյայնորեն՝ գծապատկերները և հաշվետվությունները դիտելիս:',
  'Calendar conversion' => 'Օրացույցի փոխակերպում',
  'No calendar conversion' => 'Օրացույցի փոխարկում չկա',
  'Different calendar systems are used in different parts of the world, and many other calendar systems have been used in the past. Where possible, you should enter dates using the calendar in which the event was originally recorded. You can then specify a conversion, to show these dates in a more familiar calendar. If you regularly use two calendars, you can specify two conversions and dates will be converted to both the selected calendars.' => 'Աշխարհի տարբեր մասերում օգտագործվում են տարբեր օրացույցային համակարգեր, և շատ այլ օրացույցային համակարգեր նախկինում օգտագործվել են: Հնարավորության դեպքում դուք պետք է մուտքագրեք ամսաթվերը՝ օգտագործելով այն օրացույցը, որում ի սկզբանե գրանցվել է իրադարձությունը: Այնուհետև կարող եք նշել փոխակերպումը՝ այս ամսաթվերը ավելի ծանոթ օրացույցում ցույց տալու համար: Եթե դուք պարբերաբար օգտագործում եք երկու օրացույց, կարող եք նշել երկու փոխարկում, և ամսաթվերը կվերափոխվեն երկու ընտրված օրացույցներին:',
  'Dates are only converted if they are valid for the calendar. For example, only dates between %1$s and %2$s will be converted to the French calendar and only dates after %3$s will be converted to the Gregorian calendar.' => 'Ամսաթվերը փոխարկվում են միայն այն դեպքում, եթե դրանք վավեր են օրացույցի համար: Օրինակ, միայն %1$s-ից և %2$s-ի միջև ընկած ամսաթվերը կվերածվեն ֆրանսիական օրացույցին, և միայն %3$s-ից հետո ամսաթվերը կվերածվեն Գրիգորյան օրացույցի:',
  'In some calendars, days start at midnight. In other calendars, days start at sunset. The conversion process does not take account of the time, so for any event that occurs between sunset and midnight, the conversion between these types of calendar will be one day out.' => 'Որոշ օրացույցներում օրերը սկսվում են կեսգիշերին։ Այլ օրացույցներում օրերը սկսվում են մայրամուտից։ Փոխակերպման գործընթացը հաշվի չի առնում ժամանակը, ուստի ցանկացած իրադարձության համար, որը տեղի է ունենում մայրամուտից մինչև կեսգիշեր ընկած ժամանակահատվածում, այս տեսակի օրացույցների միջև փոխարկումը կլինի մեկ օր:',
  'Add unique identifiers' => 'Ավելացրեք եզակի նույնացուցիչներ',
  'Unique identifiers allow the same record to be found in different family trees and in different systems. They will be added whenever records are created or updated. If you do not want unique identifiers to be displayed, you can hide them using the privacy rules.' => 'Եզակի նույնացուցիչները թույլ են տալիս նույն գրառումը գտնել տարբեր տոհմածառերում և տարբեր համակարգերում: Դրանք կավելացվեն, երբ գրառումները ստեղծվեն կամ թարմացվեն: Եթե դուք չեք ցանկանում, որ եզակի նույնացուցիչները ցուցադրվեն, կարող եք թաքցնել դրանք՝ օգտագործելով գաղտնիության կանոնները:',
  'Genealogy contact' => 'Ծագումնաբանության կոնտակտ',
  'The individual to contact about the genealogy data on this website.' => 'Անհատը, ում հետ կապվելու է այս կայքի ծագումնաբանական տվյալների հետ:',
  'Technical help contact' => 'Տեխնիկական օգնության կապ',
  'The individual to be contacted about technical questions or errors encountered on your website.' => 'Անհատը, որին պետք է կապ հաստատել ձեր կայքում հանդիպող տեխնիկական հարցերի կամ սխալների մասին:',
  'Add to TITLE header tag' => 'Ավելացնել TITLE վերնագրի պիտակին',
  'This text will be appended to each page title. It will be shown in the browser’s title bar, bookmarks, etc.' => 'Այս տեքստը կկցվի յուրաքանչյուր էջի վերնագրին: Այն կցուցադրվի բրաուզերի վերնագրի տողում, էջանիշերում և այլն:',
  'Description META tag' => 'Նկարագրություն META պիտակ',
  'Search engines may use this description of your site in their search results.' => 'Որոնման համակարգերը կարող են օգտագործել ձեր կայքի այս նկարագրությունը իրենց որոնման արդյունքներում:',
  'This folder will be used to store the media files for this family tree.' => 'Այս թղթապանակը կօգտագործվի այս տոհմածառի մեդիա ֆայլերը պահելու համար:',
  'If you select a different folder, you must also move any media files from the existing folder to the new one.' => 'Եթե ընտրեք այլ պանակ, դուք պետք է նաև տեղափոխեք ցանկացած մեդիա ֆայլ գոյություն ունեցող պանակից նորը:',
  'If two family trees use the same media folder, then they will be able to share media files. If they use different media folders, then their media files will be kept separate.' => 'Եթե երկու տոհմածառ օգտագործում են նույն մեդիա թղթապանակը, ապա նրանք կկարողանան կիսվել մեդիա ֆայլերով: Եթե նրանք օգտագործում են տարբեր մեդիա թղթապանակներ, ապա նրանց մեդիա ֆայլերը կպահվեն առանձին:',
  'Who can upload new media files' => 'Ով կարող է վերբեռնել նոր մեդիա ֆայլեր',
  'If you are concerned that users might upload inappropriate images, you can restrict media uploads to managers only.' => 'Եթե մտավախություն ունեք, որ օգտատերերը կարող են վերբեռնել ոչ պատշաճ պատկերներ, կարող եք սահմանափակել մեդիա վերբեռնումները միայն մենեջերների համար:',
  'Show a download link in the media viewer' => 'Ցույց տալ ներբեռնման հղումը մեդիա դիտիչում',
  'This option will make it easier for users to download images.' => 'Այս տարբերակը օգտվողների համար կհեշտացնի նկարներ ներբեռնելը:',
  'Thumbnail images' => 'Մանրապատկերների պատկերներ',
  'Show thumbnail images in charts and family groups.' => 'Ցույց տալ մանրապատկերների պատկերները գծապատկերներում և ընտանեկան խմբերում:',
  'Use silhouettes' => 'Օգտագործեք ուրվանկարներ',
  'Use silhouette images when no highlighted image for that individual has been specified. The images used are specific to the sex of the individual in question.' => 'Օգտագործեք ուրվագիծ պատկերներ, երբ նշված անհատի համար ընդգծված պատկեր չի նշվել: Օգտագործված պատկերները հատուկ են տվյալ անհատի սեռին:',
  'Watermarks' => 'Ջրի նշիչներ',
  'Images without watermarks' => 'Պատկերներ՝ առանց ջրանիշի',
  'Watermarks are optional and normally shown just to visitors.' => 'Ջրի նիշերը կամընտիր են և սովորաբար ցուցադրվում են միայն այցելուներին:',
  'Surname list style' => 'Ազգանունների ցանկի ոճը',
  'Maximum number of surnames on individual list' => 'Անհատական ցուցակում ազգանունների առավելագույն քանակը',
  'Long lists of individuals with the same surname can be broken into smaller sub-lists according to the first letter of the individual’s given name.<br><br>This option determines when sub-listing of surnames will occur. To disable sub-listing completely, set this option to zero.' => 'Նույն ազգանունով անհատների երկար ցուցակները կարելի է բաժանել ավելի փոքր ենթացուցակների՝ ըստ տվյալ անհատի անվան առաջին տառի:<br><br>Այս տարբերակը որոշում է, թե երբ տեղի կունենա ազգանունների ենթացանկը: Ենթացուցակը ամբողջությամբ անջատելու համար այս տարբերակը սահմանեք զրոյի:',
  'Estimated dates for birth and death' => 'Ծննդյան և մահվան գնահատված ամսաթվերը',
  'This option controls whether or not to show estimated dates for birth and death instead of leaving blanks on individual lists and charts for individuals whose dates are not known.' => 'Այս ընտրանքը վերահսկում է՝ ցույց տալ ծննդյան և մահվան մոտավոր ամսաթվերը, թե ոչ՝ առանձին ցուցակներում և գծապատկերներում դատարկ թողնելու փոխարեն այն անհատների համար, որոնց ամսաթվերը հայտնի չեն:',
  'The date and time of the last update' => 'Վերջին թարմացման ամսաթիվը և ժամը',
  'Age of parents next to child’s birthdate' => 'Ծնողների տարիքը երեխայի ծննդյան ամսաթվի կողքին',
  'This option controls whether or not to show age of father and mother next to child’s birthdate on charts.' => 'Այս ընտրանքը վերահսկում է՝ գծապատկերներում երեխայի ծննդյան ամսաթվի կողքին ցույց տալ հոր և մոր տարիքը, թե ոչ:',
  'Other facts to show in charts' => 'Այլ փաստեր՝ ցույց տալու գծապատկերներում',
  'Individual pages' => 'Անհատական էջեր',
  'Show the events of close relatives on the individual page' => 'Ցույց տալ մերձավոր ազգականների իրադարձությունները անհատական էջում',
  'Fact icons' => 'Փաստերի պատկերակներ',
  'Some themes can display icons on the “Facts and events” tab.' => 'Որոշ թեմաներ կարող են պատկերակներ ցուցադրել «Փաստեր և իրադարձություններ» ներդիրում:',
  'Automatically expand notes' => 'Ավտոմատ ընդլայնել նշումները',
  'This option controls whether or not to automatically display content of a <i>Note</i> record on the Individual page.' => 'Այս ընտրանքը վերահսկում է անհատական էջում <i>Նշում</i> գրառման բովանդակությունը ինքնաբերաբար ցուցադրել, թե ոչ:',
  'Automatically expand sources' => 'Ավտոմատ ընդլայնել աղբյուրները',
  'This option controls whether or not to automatically display content of a <i>Source</i> record on the Individual page.' => 'Այս ընտրանքը կարգավորում է անհատական էջում <i>Աղբյուր</i> գրառման բովանդակությունը ինքնաբերաբար ցուցադրել, թե ոչ:',
  'Abbreviate place names' => 'Համառոտ տեղանուններ',
  'first' => 'առաջին',
  'last' => 'վերջին',
  'Show the [first/last] [N] parts of a place name.first' => 'առաջին',
  'Show the [first/last] [N] parts of a place name.last' => 'վերջին',
  'Show the %1$s %2$s parts of a place name.' => 'Ցույց տալ տեղանունի %1$s %2$s մասերը:',
  'Place names are frequently too long to fit on charts, lists, etc. They can be abbreviated by showing just the first few parts of the name, such as <i>village, county</i>, or the last few part of it, such as <i>region, country</i>.' => 'Տեղանունները հաճախ չափազանց երկար են, որպեսզի տեղավորվեն գծապատկերներում, ցուցակներում և այլն: Դրանք կարող են կրճատվել՝ ցույց տալով անվան միայն առաջին մի քանի մասերը, օրինակ՝ <i>գյուղ, շրջան</i> կամ վերջին մի մասը, օրինակ՝ <i>տարածաշրջան, երկիր</i>:',
  'Format text and notes' => 'Ձևաչափեք տեքստը և նշումները',
  'To ensure compatibility with other genealogy applications, notes, text, and transcripts should be recorded in simple, unformatted text. However, formatting is often desirable to aid presentation, comprehension, etc.' => 'Տոհմաբանական այլ հավելվածների հետ համատեղելիություն ապահովելու համար նշումները, տեքստը և տառադարձումները պետք է գրանցվեն պարզ, չձևաչափված տեքստով: Այնուամենայնիվ, ձևաչափումը հաճախ ցանկալի է, որպեսզի օգնի ներկայացմանը, ըմբռնմանը և այլն:',
  'Markdown is a simple system of formatting, used on websites such as Wikipedia. It uses unobtrusive punctuation characters to create headings and sub-headings, bold and italic text, lists, tables, etc.' => 'Markdown-ը ֆորմատավորման պարզ համակարգ է, որն օգտագործվում է այնպիսի կայքերում, ինչպիսին է Վիքիպեդիան։ Այն օգտագործում է աննկատ կետադրական նիշեր՝ վերնագրեր և ենթավերնագրեր, թավ և շեղ տեքստեր, ցուցակներ, աղյուսակներ և այլն ստեղծելու համար:',
  'Allow users to see raw GEDCOM records' => 'Թույլ տվեք օգտվողներին տեսնել չմշակված GEDCOM գրառումները',
  'Setting this to <b>Yes</b> will place links on individuals, sources, and families to let users bring up another window containing the raw data taken right out of the GEDCOM file.' => 'Սահմանելով սա <b>Այո</b>-ը, հղումներ կտեղադրվեն անհատների, աղբյուրների և ընտանիքների վրա, որոնք թույլ կտան օգտատերերին բացել մեկ այլ պատուհան, որը պարունակում է անմիջապես GEDCOM ֆայլից վերցված չմշակված տվյալները:',
  'Many genealogy programs create GEDCOM files with custom tags, and webtrees understands most of them. When unrecognized tags are found, this option lets you choose whether to ignore them or display a warning message.' => 'Շատ ծագումնաբանական ծրագրեր ստեղծում են GEDCOM ֆայլեր հատուկ պիտակներով, և webtrees-ը հասկանում է դրանցից շատերը: Երբ հայտնաբերվում են չճանաչված պիտակներ, այս տարբերակը թույլ է տալիս ընտրել՝ անտեսե՞լ դրանք, թե՞ ցուցադրել նախազգուշական հաղորդագրություն:',
  'Some pages can display the number of times that they have been visited.' => 'Որոշ էջեր կարող են ցույց տալ, թե քանի անգամ են այցելել:',
  'Edit preferences' => 'Խմբագրել նախապատվությունները',
  'Facts for individual records' => 'Փաստեր անհատական գրառումների համար',
  'Facts for new individuals' => 'Փաստեր նոր անհատների համար',
  'Quick individual facts' => 'Արագ անհատական փաստեր',
  'The most common individual facts and events are listed separately, so that they can be added more easily.' => 'Ամենատարածված անհատական փաստերն ու իրադարձությունները թվարկված են առանձին, որպեսզի դրանք ավելի հեշտ ավելացվեն:',
  'Facts for family records' => 'Փաստեր ընտանեկան գրառումների համար',
  'Facts for new families' => 'Փաստեր նորաստեղծ ընտանիքների համար',
  'Quick family facts' => 'Արագ ընտանեկան փաստեր',
  'The most common family facts and events are listed separately, so that they can be added more easily.' => 'Ամենատարածված ընտանեկան փաստերն ու իրադարձությունները թվարկված են առանձին, որպեսզի դրանք ավելի հեշտ ավելացվեն:',
  'Other preferences' => 'Այլ նախասիրություններ',
  'Surname tradition' => 'Ազգանունի ավանդույթ',
  'When you add a new family member, a default surname can be provided. This surname will depend on the local tradition.' => 'Երբ դուք ավելացնում եք ընտանիքի նոր անդամ, կարող է տրվել կանխադրված ազգանուն: Այս ազգանունը կախված կլինի տեղական ավանդույթից։',
  'Keep the existing “last change” information' => 'Պահպանեք գոյություն ունեցող «վերջին փոփոխության» տեղեկատվությունը',
  'When a record is edited, the user and timestamp are recorded. Sometimes it is desirable to keep the existing “last change” information, for example when making minor corrections to someone else’s data. This option controls whether this feature is selected by default.' => 'Երբ գրառումը խմբագրվում է, օգտագործողը և ժամադրոշմը գրանցվում են: Երբեմն ցանկալի է պահպանել գոյություն ունեցող «վերջին փոփոխության» տեղեկատվությունը, օրինակ՝ ուրիշի տվյալների աննշան ուղղումներ կատարելիս: Այս ընտրանքը վերահսկում է, թե արդյոք այս ֆունկցիան ընտրված է լռելյայնորեն:',
  'Apply these preferences to all family trees' => 'Կիրառեք այս նախապատվությունները բոլոր տոհմածառերին',
  'Apply these preferences to new family trees' => 'Կիրառեք այս նախապատվությունները նոր տոհմածառերի վրա',
  'Show the family tree' => 'Ցույց տալ տոհմածառը',
  'visitors' => 'այցելուներ',
  'members' => 'անդամներ',
  'Enabling this option will force all visitors to sign in before they can view any data on the website.' => 'Այս ընտրանքի ակտիվացումը բոլոր այցելուներին կստիպի մուտք գործել՝ նախքան կայքի որևէ տվյալ դիտելը:',
  'Show dead individuals' => 'Ցույց տալ մահացած անձանց',
  'Set the privacy access level for all dead individuals.' => 'Սահմանեք գաղտնիության հասանելիության մակարդակը բոլոր մահացած անձանց համար:',
  'Age at which to assume an individual is dead' => 'Տարիքը, երբ կարելի է ենթադրել, որ անհատը մահացել է',
  'If this individual has any events other than death, burial, or cremation more recent than this number of years, they are considered to be “alive”. Children’s birth dates are considered to be such events for this purpose.' => 'Եթե այս անձը մահից, թաղումից կամ դիակիզումից բացի այլ իրադարձություններ ունի այս թվից ավելի վերջին, ապա նա համարվում է «կենդանի»: Այդ նպատակով երեխաների ծննդյան տարեթվերը համարվում են նման իրադարձություններ:',
  'Show living individuals' => 'Ցույց տալ կենդանի անհատներին',
  'If you show living individuals to visitors, all other privacy restrictions are ignored. Do this only if all the data in your tree is public.' => 'Եթե այցելուներին ցույց եք տալիս կենդանի անհատներին, գաղտնիության մնացած բոլոր սահմանափակումներն անտեսվում են: Դա արեք միայն այն դեպքում, եթե ձեր ծառի բոլոր տվյալները հրապարակային են:',
  'Extend privacy to dead individuals' => 'Ընդլայնել գաղտնիությունը մահացած անձանց վրա',
  'born in the last %1$s years or died in the last %2$s years' => 'ծնվել է վերջին %1$s տարում կամ մահացել վերջին %2$s տարում',
  'In some countries, privacy laws apply not only to living individuals, but also to those who have died recently. This option will allow you to extend the privacy rules for living individuals to those who were born or died within a specified number of years. Leave these values empty to disable this feature.' => 'Որոշ երկրներում գաղտնիության մասին օրենքները կիրառվում են ոչ միայն կենդանի անհատների, այլև վերջերս մահացածների նկատմամբ: Այս տարբերակը թույլ կտա ձեզ ընդլայնել կենդանի անհատների գաղտնիության կանոնները նրանց վրա, ովքեր ծնվել կամ մահացել են որոշակի տարիների ընթացքում: Թողեք այս արժեքները դատարկ՝ այս գործառույթն անջատելու համար:',
  'Show names of private individuals' => 'Ցույց տալ մասնավոր անձանց անունները',
  'managers' => 'մենեջերներ',
  'This option will show the names (but no other details) of private individuals. Individuals are private if they are still alive or if a privacy restriction has been added to their individual record. To hide a specific name, add a privacy restriction to that name record.' => 'Այս տարբերակը ցույց կտա մասնավոր անձանց անունները (բայց ոչ այլ մանրամասներ): Անհատները մասնավոր են, եթե նրանք դեռ ողջ են կամ եթե գաղտնիության սահմանափակում է ավելացվել նրանց անհատական գրառումներին: Կոնկրետ անունը թաքցնելու համար ավելացրեք գաղտնիության սահմանափակում այդ անվանագրում:',
  'Show private relationships' => 'Ցույց տալ անձնական հարաբերությունները',
  'This option will retain family links in private records. This means that you will see empty “private” boxes on the pedigree chart and on other charts with private individuals.' => 'Այս տարբերակը կպահի ընտանեկան կապերը մասնավոր գրառումներում: Սա նշանակում է, որ դուք կտեսնեք դատարկ «մասնավոր» տուփեր տոհմային աղյուսակում և այլ գծապատկերներում մասնավոր անձանց հետ:',
  'Privacy restrictions' => 'Գաղտնիության սահմանափակումներ',
  'You can set the access for a specific record, fact, or event by adding a restriction to it. If a record, fact, or event does not have a restriction, the following default restrictions will be used.' => 'Դուք կարող եք սահմանել մուտքը որոշակի ռեկորդի, փաստի կամ իրադարձության համար՝ դրան սահմանափակում ավելացնելով: Եթե գրառումը, փաստը կամ իրադարձությունը սահմանափակում չունենա, կօգտագործվեն հետևյալ լռելյայն սահմանափակումները:',
  'All records' => 'Բոլոր գրառումները',
  'Privacy restrictions - these apply to records and facts that do not contain a GEDCOM RESN tag' => 'Գաղտնիության սահմանափակումներ. դրանք վերաբերում են գրառումներին և փաստերին, որոնք չեն պարունակում GEDCOM RESN պիտակ',
  'Fact or event' => 'Փաստ կամ իրադարձություն',
  'add' => 'ավելացնել',
  'This record does not exist.' => 'Այս գրառումը գոյություն չունի։',
  'You can renumber the records in a family tree, so that these internal reference numbers are not duplicated in any other family tree.' => 'Դուք կարող եք վերահամարակալել տոհմածառի գրառումները, որպեսզի այս ներքին հղման համարները չկրկնվեն որևէ այլ տոհմածառում:',
  'This family tree has %s record which uses the same “XREF” as another family tree.' . "\0" . 'This family tree has %s records which use the same “XREF” as another family tree.' => 'Այս տոհմածառն ունի %s գրառում, որն օգտագործում է նույն «XREF»-ը որպես մեկ այլ տոհմածառ:' . "\0" . 'Այս տոհմածառն ունի %s գրառումներ, որոնք օգտագործում են նույն «XREF»-ը, ինչ մեկ այլ տոհմածառ:',
  'You can renumber this family tree.' => 'Դուք կարող եք վերահամարակալել այս տոհմածառը:',
  'Include associates' => 'Ներառեք գործընկերներին',
  'Include aliases' => 'Ներառեք փոխանունները',
  'update' => 'թարմացնել',
  'These groups of individuals are not related to %s.' => 'Անհատների այս խմբերը կապված չեն %s-ի հետ:',
  'Calculating…' => 'Հաշվարկվում է…',
  'Default family tree' => 'Կանխադրված տոհմածառ',
  'Set as default' => 'Սահմանել որպես լռելյայն',
  'Genealogy data' => 'Ծագումնաբանության տվյալներ',
  'Add unlinked records' => 'Ավելացրեք չկապված գրառումներ',
  'GEDCOM file' => 'GEDCOM ֆայլ',
  'Export' => 'Արտահանում',
  'It can take several minutes to download and install the upgrade. Be patient.' => 'Թարմացումը ներբեռնելու և տեղադրելու համար կարող է տևել մի քանի րոպե: Եղեք համբերատար։',
  'Depending on your server configuration, you may be able to upgrade automatically.' => 'Կախված ձեր սերվերի կազմաձևից, դուք կարող եք ավտոմատ կերպով թարմացնել:',
  'User’s account has been inactive too long: ' => 'Օգտատիրոջ հաշիվը չափազանց երկար ժամանակ անգործուն է. ',
  'User didn’t verify within 7 days.' => 'Օգտատերը չի հաստատել 7 օրվա ընթացքում։',
  'User not verified by administrator.' => 'Օգտատերը չի հաստատվել ադմինիստրատորի կողմից:',
  'Nothing found to cleanup' => 'Մաքրման համար ոչինչ չի գտնվել',
  'Real name' => 'Իրական անուն',
  'This is your real name, as you would like it displayed on screen.' => 'Սա ձեր իսկական անունն է, ինչպես կցանկանայիք, որ այն ցուցադրվի էկրանին:',
  'Usernames are case-insensitive and ignore accented letters, so that “chloe”, “chloë”, and “Chloe” are considered to be the same.' => 'Օգտվողի անունները մեծատառերի չափորոշիչ չեն և անտեսում են ընդգծված տառերը, ուստի «chloe», «chloë» և «Chloe» համարվում են նույնը:',
  'Use at least %s character.' . "\0" . 'Use at least %s characters.' => 'Օգտագործեք առնվազն %s նշան:' . "\0" . 'Օգտագործեք առնվազն %s կերպարներ:',
  'Passwords must be at least 8 characters long and are case-sensitive, so that “secret” is different from “SECRET”.' => 'Գաղտնաբառերը պետք է պարունակեն առնվազն 8 նիշ և ունեն մեծատառերի զգայունություն, որպեսզի «գաղտնիքը» տարբերվի «գաղտնի»ից:',
  'This email address will be used to send password reminders, website notifications, and messages from other family members who are registered on the website.' => 'Այս էլփոստի հասցեն կօգտագործվի գաղտնաբառի հիշեցումներ, կայքի ծանուցումներ և հաղորդագրություններ ուղարկելու ընտանիքի այլ անդամներից, ովքեր գրանցված են կայքում:',
  'Account approval and email verification' => 'Հաշվի հաստատում և էլփոստի հաստատում',
  'Email verified' => 'Էլփոստը հաստատված է',
  'Approved by administrator' => 'Հաստատված է ադմինիստրատորի կողմից',
  'When a user registers for an account, an email is sent to their email address with a verification link. When they follow this link, we know the email address is correct, and the “email verified” option is selected automatically.' => 'Երբ օգտատերը գրանցվում է հաշիվ, նամակ է ուղարկվում նրա էլ. հասցեին՝ հաստատման հղումով: Երբ նրանք հետևում են այս հղմանը, մենք գիտենք, որ էլփոստի հասցեն ճիշտ է, և «էլ․ հասցեն հաստատված» տարբերակը ընտրվում է ավտոմատ կերպով։',
  'If an administrator creates a user account, the verification email is not sent, and the email must be verified manually.' => 'Եթե ադմինիստրատորը ստեղծում է օգտատիրոջ հաշիվ, հաստատման նամակը չի ուղարկվում, և էլփոստը պետք է ստուգվի ձեռքով:',
  'You should not approve an account unless you know that the email address is correct.' => 'Դուք չպետք է հաստատեք հաշիվը, եթե չգիտեք, որ էլփոստի հասցեն ճիշտ է:',
  'A user will not be able to sign in until both “email verified” and “approved by administrator” are selected.' => 'Օգտատերը չի կարողանա մուտք գործել, մինչև չընտրվեն և՛ «էլ․ հասցեն հաստատված» և «հաստատված է ադմինիստրատորի կողմից»։',
  'Automatically accept changes made by this user' => 'Ինքնաբերաբար ընդունել այս օգտվողի կողմից կատարված փոփոխությունները',
  'Normally, any changes made to a family tree need to be reviewed by a moderator. This option allows a user to make changes without needing a moderator.' => 'Սովորաբար, տոհմածառում կատարված ցանկացած փոփոխություն պետք է վերանայվի մոդերատորի կողմից: Այս տարբերակը թույլ է տալիս օգտվողին փոփոխություններ կատարել առանց մոդերատորի կարիքի:',
  'Visible online' => 'Տեսանելի է առցանց',
  'Visible to other users when online' => 'Տեսանելի է այլ օգտվողների համար, երբ առցանց',
  'You can choose whether to appear in the list of users who are currently signed-in.' => 'Դուք կարող եք ընտրել, թե արդյոք հայտնվե՞լ այս պահին մուտք գործած օգտատերերի ցանկում:',
  'Preferred contact method' => 'Նախընտրելի շփման մեթոդ',
  'Site members can send each other messages. You can choose to how these messages are sent to you, or choose not receive them at all.' => 'Կայքի անդամները կարող են միմյանց հաղորդագրություններ ուղարկել: Դուք կարող եք ընտրել, թե ինչպես կուղարկվեն ձեզ այս հաղորդագրությունները, կամ ընտրել դրանք ընդհանրապես չստանալ:',
  'Administrator comments on user' => 'Ադմինիստրատորի մեկնաբանությունները օգտատիրոջ մասին',
  'Administrator' => 'Ադմինիստրատոր',
  'Access to family trees' => 'Տոհմածառերի հասանելիություն',
  'A role is a set of access rights, which give permission to view data, change preferences, etc. Access rights are assigned to roles, and roles are granted to users. Each family tree can assign different access to each role, and users can have a different role in each family tree.' => 'Դերը մուտքի իրավունքների մի շարք է, որը թույլ է տալիս դիտել տվյալները, փոխել նախապատվությունները և այլն: Մուտքի իրավունքները վերագրվում են դերերին, իսկ դերերը տրամադրվում են օգտվողներին: Յուրաքանչյուր տոհմածառ կարող է տարբեր մուտք հատկացնել յուրաքանչյուր դերին, և օգտվողները կարող են ունենալ տարբեր դեր յուրաքանչյուր տոհմածառում:',
  'Everybody has this role, including visitors to the website and search engines.' => 'Բոլորն ունեն այս դերը, ներառյալ կայքի այցելուները և որոնման համակարգերը:',
  'This role has all the permissions of the visitor role, plus any additional access granted by the family tree configuration.' => 'Այս դերն ունի այցելուի դերի բոլոր թույլտվությունները, գումարած ընտանեկան ծառի կազմաձևման կողմից տրված ցանկացած լրացուցիչ մուտք:',
  'This role has all the permissions of the member role, plus permission to add/change/delete data. Any changes will need to be reviewed by a moderator, unless the user has the “automatically accept changes” option enabled.' => 'Այս դերն ունի անդամի դերի բոլոր թույլտվությունները, գումարած տվյալներ ավելացնելու/փոխելու/ջնջելու թույլտվությունը։ Ցանկացած փոփոխություն պետք է վերանայվի մոդերատորի կողմից, բացառությամբ այն դեպքերի, երբ օգտատերը միացված չէ «ավտոմատ ընդունել փոփոխությունները» տարբերակը:',
  'This role has all the permissions of the editor role, plus permission to accept/reject changes made by other users.' => 'Այս դերն ունի խմբագրի դերի բոլոր թույլտվությունները, գումարած այլ օգտվողների կողմից կատարված փոփոխություններն ընդունելու/մերժելու թույլտվությունը:',
  'This role has all the permissions of the moderator role, plus any additional access granted by the family tree configuration, plus permission to change the settings/configuration of a family tree.' => 'Այս դերն ունի մոդերատորի դերի բոլոր թույլտվությունները, գումարած տոհմածառի կազմաձևման կողմից տրված ցանկացած լրացուցիչ մուտք, գումարած տոհմածառի կարգավորումները/կոնֆիգուրացիաները փոխելու թույլտվություն:',
  'This role has all the permissions of the manager role in all family trees, plus permission to change the settings/configuration of the website, users, and modules.' => 'Այս դերն ունի կառավարչի դերի բոլոր թույլտվությունները բոլոր տոհմածառերում, գումարած թույլտվություն փոխելու կայքի, օգտատերերի և մոդուլների կարգավորումները/կազմաձևերը:',
  'Individual record' => 'Անհատական ռեկորդ',
  'Link this user to an individual in the family tree.' => 'Կապեք այս օգտվողին տոհմածառի անհատի հետ:',
  'No' => 'Ոչ',
  'You must specify an individual record before you can restrict the user to their immediate family.' => 'Դուք պետք է նշեք անհատական գրառում, որպեսզի կարողանաք սահմանափակել օգտվողին իր անմիջական ընտանիքով:',
  'Masquerade as this user' => 'Դիմակահանդես, ինչպես այս օգտվողը',
  'Date registered' => 'Գրանցման ամսաթիվը',
  'Last signed in' => 'Վերջին անգամ մուտք է գործել',
  'Approved' => 'Հաստատված է',
  'view' => 'դիտել',
  '%s family' . "\0" . '%s families' => '%s Ընտանիք' . "\0" . '%s ընտանիքներ',
  'Show' => 'Ցույց տալ',
  'Filter' => 'Զտել',
  'All individuals' => 'Բոլոր անհատները',
  'Living individuals' => 'Կենդանի անհատներ',
  'Recent years (&lt; 100 yrs)' => 'Վերջին տարիները (< 100 տարի)',
  'Custom event' => 'Պատվերով միջոցառում',
  'View this day' => 'Դիտեք այս օրը',
  'View this month' => 'Դիտեք այս ամիս',
  'View this year' => 'Դիտեք այս տարի',
  'Links' => 'Հղումներ',
  'No results found' => 'Ոչ մի արդյունք չի գտնվել',
  'Your name' => 'Ձեր անունը',
  'unknown peopleUnknown' => 'Անհայտ',
  'This is a link to your own record in the family tree. If this is the wrong individual, contact an administrator.' => 'Սա հղում է տոհմածառի ձեր սեփական գրառումին: Եթե սա սխալ անձնավորություն է, դիմեք ադմինիստրատորին:',
  'Leave the password blank if you want to keep the current password.' => 'Գաղտնաբառը դատարկ թողեք, եթե ցանկանում եք պահպանել ընթացիկ գաղտնաբառը:',
  'Contact method' => 'Կոնտակտային մեթոդ',
  'Delete your account' => 'Ջնջել ձեր հաշիվը',
  'Drag the blocks to change their position.' => 'Քաշեք բլոկները՝ փոխելու իրենց դիրքը:',
  'Add more blocks from the following list.' => 'Ավելացրեք ավելի շատ բլոկներ հետևյալ ցուցակից:',
  'Restore the default block layout' => 'Վերականգնել բլոկի լռելյայն դասավորությունը',
  'Add a fact' => 'Ավելացնել փաստ',
  'Son' => 'Որդի',
  'Daughter' => 'Դուստր',
  'Edit with all GEDCOM tags' => 'Խմբագրել բոլոր GEDCOM պիտակներով',
  'Copy' => 'Պատճենել',
  'Are you sure you want to delete the link to “%s”?' => 'Իսկապե՞ս ուզում եք ջնջել «%s»-ի հղումը?',
  'Unlink' => 'Չեղարկել կապը',
  'Select a date' => 'Ընտրեք ամսաթիվ',
  'Edit the name' => 'Խմբագրել անունը',
  'Find a special character' => 'Գտեք հատուկ կերպար',
  'A child may have more than one set of parents. The relationship between the child and the parents can be biological, legal, or based on local culture and tradition. If no pedigree is specified, then a biological relationship will be assumed.' => 'Երեխան կարող է ունենալ մեկից ավելի ծնողներ: Երեխայի և ծնողների հարաբերությունները կարող են լինել կենսաբանական, օրինական կամ հիմնված տեղական մշակույթի և ավանդույթի վրա: Եթե տոհմային չնշված լինի, ապա կենթադրվի կենսաբանական հարաբերություն:',
  'go to new individual' => 'գնալ նոր անհատի',
  'This page allows you to bypass the usual forms, and edit the underlying data directly. It is an advanced option, and you should not use it unless you understand the GEDCOM format. If you make a mistake here, it can be difficult to fix.' => 'Այս էջը թույլ է տալիս շրջանցել սովորական ձևերը և ուղղակիորեն խմբագրել հիմքում ընկած տվյալները: Դա առաջադեմ տարբերակ է, և դուք չպետք է օգտագործեք այն, քանի դեռ չեք հասկանում GEDCOM ձևաչափը: Եթե այստեղ սխալ եք թույլ տալիս, ապա այն կարող է դժվար լինել ուղղել:',
  'You can download a copy of the GEDCOM specification from %s.' => 'Դուք կարող եք ներբեռնել GEDCOM բնութագրի պատճենը %s-ից:',
  'sort by date of birth' => 'տեսակավորել ըստ ծննդյան ամսաթվի',
  'Spouses' => 'Ամուսիններ',
  'When an individual has more than one spouse, you should sort the families in date order.' => 'Երբ անհատն ունի մեկից ավելի ամուսին, դուք պետք է դասավորեք ընտանիքները ըստ ամսաթվերի:',
  'sort by date of marriage' => 'տեսակավորել ըստ ամուսնության ամսաթվի',
  'An individual can have more than one set of parents. For example, birth and adopted.' => 'Անհատը կարող է ունենալ մեկից ավելի ծնողներ: Օրինակ՝ ծնունդը և որդեգրումը։',
  'The first family in the list will be used in charts, lists, reports, etc.' => 'Ցանկի առաջին ընտանիքը կօգտագործվի գծապատկերներում, ցուցակներում, հաշվետվություններում և այլն:',
  'Hello %s…' => 'Բարև %s…',
  'The administrator at the webtrees site %s has approved your application for an account. You may now sign in by accessing the following link: %s' => '%s webtrees կայքի ադմինիստրատորը հաստատել է ձեր դիմումը հաշվի համար: Այժմ կարող եք մուտք գործել՝ մուտք գործելով հետևյալ հղումը՝ %s',
  'You sent the following message to a webtrees user:' => 'Դուք ուղարկել եք հետևյալ հաղորդագրությունը webtrees-ի օգտատիրոջը:',
  'This message was sent while viewing the following URL: ' => 'Այս հաղորդագրությունն ուղարկվել է հետևյալ URL-ը դիտելիս. ',
  '%1$s (%2$s)' => '%1$s (%2$s)',
  '%s sent you the following message.' => '%s-ը ձեզ ուղարկել է հետևյալ հաղորդագրությունը.',
  'To set a new password, follow this link.' => 'Նոր գաղտնաբառ սահմանելու համար անցեք այս հղմանը:',
  'If you did not request a new password, please ignore this message.' => 'Եթե դուք չեք խնդրել նոր գաղտնաբառ, խնդրում ենք անտեսել այս հաղորդագրությունը:',
  'Hello administrator…' => 'Բարև ադմինիստրատոր…',
  'A prospective user has registered with webtrees at %s.' => 'Հնարավոր օգտվողը գրանցվել է webtrees-ում %s-ում:',
  'Comments' => 'Մեկնաբանություններ',
  'The user has been sent an email with the information necessary to confirm the access request.' => 'Օգտագործողին ուղարկվել է էլեկտրոնային նամակ՝ մուտքի հարցումը հաստատելու համար անհրաժեշտ տեղեկություններով:',
  'You will be informed by email when this prospective user has confirmed the request. You can then complete the process by activating the username. The new user will not be able to sign in until you activate the account.' => 'Դուք էլփոստով կտեղեկացվեք, երբ այս ապագա օգտվողը հաստատի հարցումը: Այնուհետև կարող եք ավարտել գործընթացը՝ ակտիվացնելով օգտվողի անունը: Նոր օգտվողը չի կարողանա մուտք գործել, քանի դեռ չեք ակտիվացնել հաշիվը:',
  'You (or someone claiming to be you) has requested an account at %1$s using the email address %2$s.' => 'Դուք (կամ ինչ-որ մեկը, որը պնդում է, որ դուք եք) հաշիվ եք խնդրել %1$s-ում՝ օգտագործելով %2$s էլ.',
  'Follow this link to verify your email address.' => 'Հետևեք այս հղմանը ձեր էլ.փոստի հասցեն հաստատելու համար:',
  'If you didn’t request an account, you can just delete this message.' => 'Եթե դուք հաշիվ չեք խնդրել, կարող եք պարզապես ջնջել այս հաղորդագրությունը:',
  'A new user (%1$s) has requested an account (%2$s) and verified an email address (%3$s).' => 'Նոր օգտվողը (%1$s) հաշիվ է խնդրել (%2$s) և հաստատել էլփոստի հասցեն (%3$s):',
  'You need to review the account details.' => 'Դուք պետք է վերանայեք հաշվի մանրամասները:',
  'Set the status to “approved”.' => 'Կարգավիճակը դրեք «հաստատված»:',
  'Set the access level for each tree.' => 'Սահմանեք մուտքի մակարդակը յուրաքանչյուր ծառի համար:',
  'Link the user account to an individual.' => 'Օգտատիրոջ հաշիվը կապեք անհատի հետ:',
  'Oops! The webserver is unable to connect to the database server. It could be busy, undergoing maintenance, or simply broken. You should <a href="index.php">try again</a> in a few minutes or contact the website administrator.' => 'Վա՜յ Վեբսերվերը չի կարողանում միանալ տվյալների բազայի սերվերին: Այն կարող է զբաղված լինել, տեխնիկական սպասարկում կամ պարզապես կոտրվել: Դուք պետք է <a href="index.php">փորձեք նորից</a> մի քանի րոպեից կամ կապվեք կայքի ադմինիստրատորի հետ:',
  'If you are the website administrator, you should check that:' => 'Եթե դուք կայքի ադմինիստրատորն եք, ապա պետք է ստուգեք, որ:',
  'the database connection settings in the file “/data/config.ini.php” are still correct' => 'տվյալների բազայի միացման կարգավորումները «/data/config.ini.php» ֆայլում դեռ ճիշտ են',
  'the folder “/data” and the file “/data/config.ini.php” have access permissions that allow the webserver to read them' => '«/data» թղթապանակը և «/data/config.ini.php» ֆայլն ունեն մուտքի թույլտվություններ, որոնք թույլ են տալիս վեբսերվերին կարդալ դրանք',
  'you can connect to the database using other applications, such as phpmyadmin' => 'դուք կարող եք միանալ տվյալների բազային՝ օգտագործելով այլ հավելվածներ, օրինակ՝ phpmyadmin',
  'If you cannot resolve the problem yourself, you can ask for help on the forums at <a href="https://webtrees.net">webtrees.net</a>.' => 'Եթե դուք ինքներդ չեք կարող լուծել խնդիրը, կարող եք օգնություն խնդրել <a href="https://webtrees.net">webtrees.net</a> ֆորումներում:',
  'An unexpected database error occurred.' => 'Տվյալների բազայի անսպասելի սխալ տեղի ունեցավ:',
  'The webtrees developers would be very interested to learn about this error. If you contact them, they will help you resolve the problem.' => 'Webtrees-ի մշակողները շատ հետաքրքրված կլինեն իմանալ այս սխալի մասին: Եթե դիմեք նրանց, նրանք կօգնեն ձեզ լուծել խնդիրը:',
  'This user account does not have access to any tree.' => 'Այս օգտվողի հաշիվը մուտք չունի որևէ ծառի:',
  '(on the date of death)' => '(մահվան օրը)',
  '(%s after death)' => '(%s մահից հետո)',
  'Mother’s age' => 'մոր տարիքը',
  'Father’s age' => 'Հոր տարիքը',
  'Parent’s age' => 'Ծնողի տարիքը',
  '%s child' . "\0" . '%s children' => '%s երեխա' . "\0" . '%s Երեխաներ',
  'Add a media object' => 'Ավելացնել մեդիա օբյեկտ',
  'Deleting the family will unlink all of the individuals from each other but will leave the individuals in place. Are you sure you want to delete this family?' => 'Ընտանիքը ջնջելու դեպքում բոլոր անհատները կհեռացվեն միմյանցից, սակայն անհատները կթողնեն իրենց տեղում: Իսկապե՞ս ուզում եք ջնջել այս ընտանիքը?',
  'You should review the deletion and then accept or reject it.accept' => 'ընդունել',
  'You should review the deletion and then accept or reject it.reject' => 'մերժել',
  'This family has been deleted. You should review the deletion and then %1$s or %2$s it.' => 'Այս ընտանիքը ջնջվել է: Դուք պետք է վերանայեք ջնջումը, այնուհետև %1$s կամ %2$s այն:',
  'This family has been deleted. The deletion will need to be reviewed by a moderator.' => 'Այս ընտանիքը ջնջվել է: Ջնջումը պետք է վերանայվի մոդերատորի կողմից:',
  'You should review the changes and then accept or reject them.accept' => 'ընդունել',
  'You should review the changes and then accept or reject them.reject' => 'մերժել',
  'This family has been edited. You should review the changes and then %1$s or %2$s them.' => 'Այս ընտանիքը խմբագրվել է: Դուք պետք է վերանայեք փոփոխությունները, այնուհետև %1$s կամ %2$s դրանք:',
  'This family has been edited. The changes need to be reviewed by a moderator.' => 'Այս ընտանիքը խմբագրվել է: Փոփոխությունները պետք է վերանայվեն մոդերատորի կողմից:',
  'No facts exist for this family.' => 'Այս ընտանիքի համար փաստեր չկան.',
  'Username or email address' => 'Օգտվողի անունը կամ էլփոստի հասցեն',
  'Data fixes can require lots of slow calculations, so it is not possible to create an exact list of records that need to be updated.' => 'Տվյալների շտկումները կարող են պահանջել շատ դանդաղ հաշվարկներ, ուստի հնարավոր չէ թարմացվող գրառումների ճշգրիտ ցուցակ ստեղծել:',
  'For example, we can quickly find individuals that do not have a death event, but it is much slower to calculate if the individual is dead.' => 'Օրինակ, մենք կարող ենք արագ գտնել անհատներ, որոնց մոտ մահվան դեպք չկա, բայց շատ ավելի դանդաղ է հաշվարկել, թե արդյոք անհատը մահացել է:',
  'This list is created using a simple (but fast) search, and therefore includes records that will not be updated.' => 'Այս ցուցակը ստեղծվում է պարզ (բայց արագ) որոնման միջոցով և, հետևաբար, ներառում է գրառումներ, որոնք չեն թարմացվելու:',
  'Dates are stored using English abbreviations and keywords. Shortcuts are available as alternatives to these abbreviations and keywords.' => 'Ամսաթվերը պահվում են՝ օգտագործելով անգլերեն հապավումները և հիմնաբառերը: Դյուրանցումները հասանելի են որպես այս հապավումների և հիմնաբառերի այլընտրանք:',
  'Shortcut' => 'Դյուրանցում',
  'Date ranges are used to indicate that an event, such as a birth, happened on an unknown date within a possible range.' => 'Ամսաթվերի միջակայքերը օգտագործվում են ցույց տալու համար, որ իրադարձությունը, ինչպիսին ծնունդն է, տեղի է ունեցել անհայտ ամսաթվի հնարավոր տիրույթում:',
  'Date periods are used to indicate that a fact, such as an occupation, continued for a period of time.' => 'Ամսաթվերի ժամկետները օգտագործվում են ցույց տալու համար, որ փաստը, ինչպիսին է զբաղմունքը, շարունակվել է որոշակի ժամանակահատվածում:',
  'Date period' => 'Ամսաթվի ժամկետը',
  'Simple dates are assumed to be in the gregorian calendar. To specify a date in another calendar, add a keyword before the date. This keyword is optional if the month or year format make the date unambiguous.' => 'Ենթադրվում է, որ պարզ ամսաթվերը գրված են Գրիգորյան օրացույցում: Մեկ այլ օրացույցում ամսաթիվ նշելու համար ավելացրեք հիմնաբառ ամսաթվից առաջ: Այս հիմնաբառը պարտադիր չէ, եթե ամսվա կամ տարվա ձևաչափը ամսաթիվը դարձնում է միանշանակ:',
  'In many cultures it is customary to have a traditional name spelled in the traditional characters and also a romanized version of the name as it would be spelled or pronounced in languages based on the Latin alphabet, such as English.<br><br>If you prefer to use the Latin alphabet to enter the name in the standard name fields, then you can use this field to enter the same name in the non-Latin alphabet such as Greek, Hebrew, Russian, Arabic, or Chinese. Both versions of the name will appear in lists and charts.<br><br>Although this field is labeled “Hebrew”, it is not restricted to containing only Hebrew characters.' => 'Շատ մշակույթներում ընդունված է ավանդական անունն ուղղագրել ավանդական գրանշաններով, ինչպես նաև անվան հռոմեական տարբերակ, ինչպես դա գրվում կամ արտասանվում է լատինական այբուբենի վրա հիմնված լեզուներով, օրինակ՝ անգլերենով:<br><br>Եթե նախընտրում եք օգտագործել լատինական այբուբենը՝ անունը ստանդարտ անվան դաշտերում մուտքագրելու համար, ապա կարող եք օգտագործել այս դաշտը՝ նույն անունը Latin, ռուսերեն, եբրայերեն, al-չինարեն, ոչ-չինարեն, ոչ-չինարեն, ոչ-չինարեն, ոչ-չինարեն, ոչ-չինարեն, ոչ-չինարեն կամ ոչ-չինարեն աբեթ մուտքագրելու համար: Անվան երկու տարբերակները կհայտնվեն ցուցակներում և գծապատկերներում:<br><br>Չնայած այս դաշտը պիտակավորված է «եբրայերեն», այն չի սահմանափակվում միայն եբրայերեն գրանշաններով:',
  'A media object is a record in the family tree which contains information about a media file. This information may include a title, a copyright notice, a transcript, privacy restrictions, etc. The media file, such as the photo or video, can be stored locally (on this webserver) or remotely (on a different webserver).' => 'Մեդիա օբյեկտը տոհմածառի գրառում է, որը պարունակում է տեղեկատվություն մեդիա ֆայլի մասին: Այս տեղեկատվությունը կարող է ներառել վերնագիր, հեղինակային իրավունքի մասին ծանուցում, տառադարձում, գաղտնիության սահմանափակումներ և այլն: Մեդիա ֆայլը, ինչպիսին է լուսանկարը կամ տեսանյութը, կարող է պահվել տեղական (այս վեբսերվերի վրա) կամ հեռակա (այլ վեբսերվերի վրա):',
  'The <b>name</b> field contains the individual’s full name, as they would have spelled it or as it was recorded. This is how it will be displayed on screen. It uses standard genealogy annotations to identify different parts of the name.' => '<b>name</b> դաշտը պարունակում է անհատի լրիվ անունը, ինչպես նրանք կգրեին կամ այնպես, ինչպես գրանցվել է: Այսպես այն կցուցադրվի էկրանին։ Այն օգտագործում է ստանդարտ ծագումնաբանական ծանոթագրություններ անվանման տարբեր մասերը բացահայտելու համար:',
  'The surname is enclosed by slashes: <%s>John Paul /Smith/<%s>' => 'Ազգանունը կցվում է շեղերով՝ <%s>Ջոն Փոլ /Սմիթ/<%s>',
  'If the surname is unknown, use empty slashes: <%s>Mary //<%s>' => 'Եթե ազգանունն անհայտ է, օգտագործեք դատարկ շեղեր՝ <%s>Մերի //<%s>',
  'If an individual has two separate surnames, both should be enclosed by slashes: <%s>José Antonio /Gómez/ /Iglesias/<%s>' => 'Եթե անհատն ունի երկու առանձին ազգանուն, երկուսն էլ պետք է փակվեն շեղերով՝ <%s>Խոսե Անտոնիո /Գոմես/ /Իգլեսիաս/<%s>',
  'If an individual does not have a surname, no slashes are needed: <%s>Jón Einarsson<%s>' => 'Եթե անհատը ազգանուն չունի, ապա կտրվածքի կարիք չկա. <%s>Ջոն Էյնարսոն<%s>',
  'If an individual was not known by their first given name, the preferred name should be indicated with an asterisk: <%s>John Paul* /Smith/<%s>' => 'Եթե անհատը հայտնի չէ իր առաջին անունով, նախընտրելի անունը պետք է նշվի աստղանիշով՝ <%s>Ջոն Փոլ* /Սմիթ/<%s>',
  'If an individual was known by a nickname which is not part of their formal name, it should be enclosed by quotation marks. For example, <%s>John &quot;Nobby&quot; /Clark/<%s>.' => 'Եթե անհատը հայտնի էր մականունով, որը նրա պաշտոնական անվան մաս չէ, այն պետք է փակցվի չակերտներով: Օրինակ՝ <%s>Ջոն &laquo;Նոբբի&raquo; /Clark/<%s>:',
  'When you add, edit, or delete information, the changes are not saved immediately. Instead, they are kept in a “pending” area. These pending changes need to be reviewed by a moderator before they are accepted.' => 'Երբ ավելացնում եք, խմբագրում կամ ջնջում եք տեղեկատվություն, փոփոխություններն անմիջապես չեն պահպանվում: Փոխարենը, դրանք պահվում են «սպասող» տարածքում։ Այս սպասվող փոփոխությունները պետք է վերանայվեն մոդերատորի կողմից՝ նախքան դրանք ընդունելը:',
  'This process allows the site’s owner to ensure that the new information follows the site’s standards and conventions, has proper source attributions, etc.' => 'Այս գործընթացը թույլ է տալիս կայքի սեփականատիրոջը համոզվել, որ նոր տեղեկատվությունը համապատասխանում է կայքի չափանիշներին և կոնվենցիաներին, ունի աղբյուրների համապատասխան վերագրումներ և այլն:',
  'Pending changes are only shown when your account has permission to edit. When you sign out, you will no longer be able to see them. Also, pending changes are only shown on certain pages. For example, they are not shown in lists, reports, or search results.' => 'Սպասող փոփոխությունները ցուցադրվում են միայն այն ժամանակ, երբ ձեր հաշիվը խմբագրելու թույլտվություն ունի: Երբ դուրս գաք, դուք այլևս չեք կարողանա տեսնել դրանք: Բացի այդ, սպասվող փոփոխությունները ցուցադրվում են միայն որոշակի էջերում: Օրինակ, դրանք չեն ցուցադրվում ցուցակներում, հաշվետվություններում կամ որոնման արդյունքներում:',
  'Each user account has an option to “automatically accept changes”. When this is enabled, any changes made by that user are saved immediately. Many administrators enable this for their own user account.' => 'Յուրաքանչյուր օգտվողի հաշիվ ունի «ավտոմատ կերպով ընդունել փոփոխությունները» տարբերակ: Երբ սա միացված է, այդ օգտվողի կողմից կատարված ցանկացած փոփոխություն անմիջապես պահվում է: Շատ ադմինիստրատորներ դա թույլ են տալիս իրենց սեփական օգտատիրոջ հաշվի համար:',
  'Place names should be entered as a comma-separated list, starting with the smallest place and ending with the country. For example, “Westminster, London, England”.' => 'Տեղանունները պետք է մուտքագրվեն որպես ստորակետերով բաժանված ցուցակ՝ սկսած ամենափոքր տեղից և վերջացրած երկրով: Օրինակ՝ «Վեսթմինսթեր, Լոնդոն, Անգլիա»։',
  'Place names can change over time. In genealogy, it is customary to use the current name for a town or country. The historic name can be shown in sources, notes, etc.' => 'Տեղանունները կարող են փոխվել ժամանակի ընթացքում: Ծագումնաբանության մեջ ընդունված է օգտագործել քաղաքի կամ երկրի ներկայիս անվանումը։ Պատմական անունը կարելի է ցույց տալ աղբյուրներում, նշումներում և այլն։',
  'Where a user is associated to an individual record in a family tree and has a role of member, editor, or moderator, you can prevent them from accessing the details of distant, living relations. You specify the number of relationship steps that the user is allowed to see.' => 'Եթե օգտատերը կապված է տոհմածառի առանձին գրառումների հետ և ունի անդամի, խմբագրի կամ վարողի դեր, դուք կարող եք թույլ չտալ նրան մուտք գործել հեռավոր, կենդանի հարաբերությունների մանրամասները: Դուք նշում եք հարաբերությունների քայլերի քանակը, որոնք օգտատերը կարող է տեսնել:',
  'For example, if you specify a path length of 2, the individual will be able to see their grandson (child, child), their aunt (parent, sibling), their step-daughter (spouse, child), but not their first cousin (parent, sibling, child).' => 'Օրինակ, եթե դուք նշեք 2 ուղու երկարությունը, անհատը կկարողանա տեսնել իր թոռանը (երեխա, երեխա), մորաքրոջը (ծնող, քույր կամ քույր), խորթ դստերը (ամուսին, երեխա), բայց ոչ իր առաջին զարմիկին (ծնող, քույր կամ քույր, երեխա):',
  'Note: longer path lengths require a lot of calculation, which can make your website run slowly for these users.' => 'Նշում. ավելի երկար ճանապարհների երկարությունները պահանջում են շատ հաշվարկներ, ինչը կարող է ստիպել ձեր վեբկայքը դանդաղ աշխատել այս օգտվողների համար:',
  'Restrictions can be added to records and/or facts. They restrict who can view the data and who can edit it.' => 'Սահմանափակումները կարող են ավելացվել գրառումներին և/կամ փաստերին: Նրանք սահմանափակում են, թե ով կարող է դիտել տվյալները և ովքեր կարող են խմբագրել դրանք:',
  'Note that if a user account is linked to a record, then that user will always be able to view that record.' => 'Նկատի ունեցեք, որ եթե օգտվողի հաշիվը կապված է գրառումների հետ, ապա այդ օգտվողը միշտ կկարողանա դիտել այդ գրառումը:',
  'In many cultures it is customary to have a traditional name spelled in the traditional characters and also a romanized version of the name as it would be spelled or pronounced in languages based on the Latin alphabet, such as English.<br><br>If you prefer to use a non-Latin alphabet such as Hebrew, Greek, Russian, Chinese, or Arabic to enter the name in the standard name fields, then you can use this field to enter the same name using the Latin alphabet. Both versions of the name will appear in lists and charts.<br><br>Although this field is labeled “Romanized”, it is not restricted to containing only characters based on the Latin alphabet. This might be of use with Japanese names, where three different alphabets may occur.' => 'Շատ մշակույթներում ընդունված է ավանդական անուն գրել ավանդական գրանշաններով, ինչպես նաև անվան հռոմեական տարբերակ, ինչպես դա կուղղվի կամ արտասանվի լատինական այբուբենի վրա հիմնված լեզուներով, օրինակ՝ անգլերենով:<br><br>Եթե նախընտրում եք օգտագործել ոչ լատինատառ այբուբեն, ինչպիսիք են եբրայերեն, հունարեն, ռուսերեն, չինարեն կամ արաբերեն, ապա կարող եք մուտքագրել նույն անունը ալֆա անվանման դաշտում: Անվան երկու տարբերակները կհայտնվեն ցուցակներում և գծապատկերներում:<br><br>Չնայած այս դաշտը պիտակավորված է «Ռոմանիզացված», այն չի սահմանափակվում միայն լատինատառ այբուբենի վրա հիմնված նիշեր պարունակելու համար: Սա կարող է օգտագործվել ճապոնական անունների հետ, որտեղ կարող են լինել երեք տարբեր այբուբեններ:',
  'Each source records specific events, generally for a given date range and for a place jurisdiction. For example a Census records census events and church records record birth, marriage, and death events.<br><br>Select the events that are recorded by this source from the list of events provided. The date should be specified in a range format such as <i>FROM 1900 TO 1910</i>. The place jurisdiction is the name of the lowest jurisdiction that encompasses all lower-level places named in this source. For example, “Oneida, Idaho, USA” would be used as a source jurisdiction place for events occurring in the various towns within Oneida County. “Idaho, USA” would be the source jurisdiction place if the events recorded took place not only in Oneida County but also in other counties in Idaho.' => 'Յուրաքանչյուր աղբյուր գրանցում է կոնկրետ իրադարձություններ, ընդհանուր առմամբ, տվյալ ամսաթվերի և վայրի իրավասության համար: Օրինակ՝ մարդահամարը գրանցում է մարդահամարի իրադարձությունները, իսկ եկեղեցում գրանցվում են ծննդյան, ամուսնության և մահվան դեպքերը:<br><br>Ընտրեք այն իրադարձությունները, որոնք գրանցված են այս աղբյուրի կողմից տրամադրված իրադարձությունների ցանկից: Ամսաթիվը պետք է նշվի միջակայքի ձևաչափով, ինչպիսին է <i>1900-ից մինչև 1910 թվականը</i>: Տեղի իրավասությունը ամենացածր իրավասության անունն է, որն ընդգրկում է այս աղբյուրում նշված բոլոր ցածր մակարդակի վայրերը: Օրինակ՝ «Օնեիդա, Այդահո, ԱՄՆ» կօգտագործվի որպես Օնեիդա շրջանի տարբեր քաղաքներում տեղի ունեցող իրադարձությունների աղբյուրի իրավասության վայր: «Այդահո, ԱՄՆ»-ը կլիներ աղբյուրի իրավասության վայրը, եթե արձանագրված իրադարձությունները տեղի ունենային ոչ միայն Օնեիդա գավառում, այլև Այդահոյի այլ շրջաններում:',
  'The <b>surname</b> field contains a name that is used for sorting and grouping. It can be different to the individual’s actual surname which is always taken from the <b>name</b> field. This field can be used to sort surnames with or without a prefix (Gogh / van Gogh) and to group spelling variations or inflections (Kowalski / Kowalska). If an individual needs to be listed under more than one surname, each name should be separated by a comma.' => '<b>ազգանուն</b> դաշտը պարունակում է անուն, որն օգտագործվում է տեսակավորման և խմբավորման համար: Այն կարող է տարբերվել անհատի իրական ազգանունից, որը միշտ վերցված է <b>name</b> դաշտից: Այս դաշտը կարող է օգտագործվել ազգանունները նախածանցով կամ առանց նախածանցով (Գոգ / վան Գոգ) տեսակավորելու և ուղղագրական տատանումները կամ ճեղքերը խմբավորելու համար (Կովալսկի / Կովալսկա): Եթե անհատը պետք է ցուցակագրվի մեկից ավելի ազգանվան տակ, յուրաքանչյուր անուն պետք է բաժանվի ստորակետով:',
  'previous' => 'նախորդ',
  'Share' => 'Կիսվել',
  'Add a name' => 'Ավելացրեք անուն',
  'Edit the sex' => 'Խմբագրել սեռը',
  'Are you sure you want to delete this fact?' => 'Իսկապե՞ս ուզում եք ջնջել այս փաստը?',
  'Delete this name' => 'Ջնջել այս անունը',
  'This individual has been deleted. You should review the deletion and then %1$s or %2$s it.' => 'Այս անհատը ջնջվել է: Դուք պետք է վերանայեք ջնջումը, այնուհետև %1$s կամ %2$s այն:',
  'This individual has been deleted. The deletion will need to be reviewed by a moderator.' => 'Այս անհատը ջնջվել է: Ջնջումը պետք է վերանայվի մոդերատորի կողմից:',
  'This individual has been edited. You should review the changes and then %1$s or %2$s them.' => 'Այս անհատը խմբագրվել է: Դուք պետք է վերանայեք փոփոխությունները, այնուհետև %1$s կամ %2$s դրանք:',
  'This individual has been edited. The changes need to be reviewed by a moderator.' => 'Այս անհատը խմբագրվել է: Փոփոխությունները պետք է վերանայվեն մոդերատորի կողմից:',
  'Skip to content' => 'Անցնել բովանդակությանը',
  'Play' => 'Խաղալ',
  'Stop' => 'Դադարեցրեք',
  'This website is temporarily unavailable' => 'Այս կայքը ժամանակավորապես անհասանելի է',
  'This website is down for maintenance. You should <a href="index.php">try again</a> in a few minutes.' => 'Այս կայքը անջատված է սպասարկման համար: Դուք պետք է <a href="index.php">փորձեք նորից</a> մի քանի րոպեից:',
  'Setup wizard for webtrees' => 'Վեբ ծառերի տեղադրման հրաշագործ',
  'Anniversary' => 'տարեդարձ',
  'No records to display' => 'Ցուցադրման գրառումներ չկան',
  'Showing %1$s to %2$s of %3$s' => 'Ցուցադրվում է %1$s-ից մինչև %2$s %3$s-ից',
  '(filtered from %s total entries)' => '(զտված է %s ընդհանուր գրառումներից)',
  'Display %s' => 'Ցուցադրել %s',
  'Loading…' => 'Բեռնվում է…',
  'Both alive' => 'Երկուսն էլ ողջ են',
  'Show couples where only the female partner is dead.' => 'Ցույց տվեք զույգերին, որտեղ միայն կին գործընկերն է մահացած:',
  'Widower' => 'այրի',
  'Show couples where only the male partner is dead.' => 'Ցույց տվեք զույգերին, որտեղ միայն տղամարդ գործընկերն է մահացած:',
  'Widow' => 'Այրի',
  'Show individuals who are dead or couples where both partners are dead.' => 'Ցույց տվեք մահացած անհատներին կամ զույգերին, որտեղ երկու գործընկերներն էլ մահացած են:',
  'Both dead' => 'Երկուսն էլ մահացած',
  'Show “roots” couples or individuals. These individuals may also be called “patriarchs”. They are individuals who have no parents recorded in the database.' => 'Ցույց տալ «արմատներ» զույգերին կամ անհատներին: Այս անհատներին կարելի է անվանել նաև «պատրիարքներ»: Նրանք անհատներ են, ովքեր չունեն տվյալների բազայում գրանցված ծնողներ:',
  'Roots' => 'Արմատներ',
  'Show “leaves” couples or individuals. These are individuals who are alive but have no children recorded in the database.' => 'Ցույց տվեք «տևում» զույգերին կամ անհատներին: Սրանք այն անձինք են, ովքեր ողջ են, բայց տվյալների բազայում գրանցված երեխաներ չունեն:',
  'Leaves' => 'Տերեւներ',
  'Show couples with an unknown marriage date.' => 'Ցույց տալ անհայտ ամուսնության ամսաթիվ ունեցող զույգերին:',
  'Show couples who married more than 100 years ago.' => 'Ցույց տալ զույգերին, ովքեր ամուսնացել են ավելի քան 100 տարի առաջ:',
  'Show couples who married within the last 100 years.' => 'Ցույց տալ զույգերին, ովքեր ամուսնացել են վերջին 100 տարվա ընթացքում:',
  'Show divorced couples.' => 'Ցույց տալ ամուսնալուծված զույգերին:',
  'Show couples where either partner married more than once.' => 'Ցույց տալ զույգերին, որտեղ զուգընկերներից մեկն ամուսնացել է մեկից ավելի անգամ:',
  'Multiple marriages' => 'Բազմաթիվ ամուսնություններ',
  'Show parents' => 'Ցույց տալ ծնողներին',
  'Given name' => 'Տրված անուն',
  'Mother: %s' => 'Մայրը՝ %s',
  'Father: %s' => 'Հայրը՝ %s',
  'Show only males.' => 'Ցույց տալ միայն արական սեռի ներկայացուցիչներին:',
  'Show only females.' => 'Ցույց տալ միայն իգական սեռի ներկայացուցիչներին:',
  'Show only individuals for whom the sex is not known.' => 'Ցույց տվեք միայն այն անհատներին, որոնց սեռը հայտնի չէ:',
  'Show individuals who are alive or couples where both partners are alive.' => 'Ցույց տվեք կենդանի մարդկանց կամ զույգերին, որտեղ երկու գործընկերներն էլ ողջ են:',
  'Alive' => 'Կենդանի',
  'Show individuals who died more than 100 years ago.' => 'Ցույց տալ անհատներին, ովքեր մահացել են ավելի քան 100 տարի առաջ:',
  'Show individuals who died within the last 100 years.' => 'Ցույց տալ անհատներին, ովքեր մահացել են վերջին 100 տարվա ընթացքում:',
  'Show individuals born more than 100 years ago.' => 'Ցույց տվեք ավելի քան 100 տարի առաջ ծնված անհատներին:',
  'Show individuals born within the last 100 years.' => 'Ցույց տալ վերջին 100 տարվա ընթացքում ծնված անհատներին:',
  'Sosa' => 'Սոսա',
  'Repository name' => 'Պահեստի անվանումը',
  'Submitter name' => 'Ներկայացնողի անունը',
  'Surnames' => 'Ազգանուններ',
  'Welcome to this genealogy website' => 'Բարի գալուստ այս ծագումնաբանության կայք',
  'sign in' => 'մուտք գործել',
  'Forgot password?' => 'Մոռացել եք գաղտնաբառը?',
  'The file “%s” does not exist.' => '«%s» ֆայլը գոյություն չունի:',
  'Download file' => 'Ներբեռնեք ֆայլը',
  'Re-order media files' => 'Կրկին պատվիրեք մեդիա ֆայլերը',
  'Link this media object to an individual' => 'Կապել այս մեդիա օբյեկտը անհատի հետ',
  'Link this media object to a family' => 'Այս մեդիա օբյեկտը կապեք ընտանիքի հետ',
  'Link this media object to a source' => 'Կապել այս մեդիա օբյեկտը աղբյուրի հետ',
  'This media object has been deleted. You should review the deletion and then %1$s or %2$s it.' => 'Այս մեդիա օբյեկտը ջնջվել է: Դուք պետք է վերանայեք ջնջումը, այնուհետև %1$s կամ %2$s այն:',
  'This media object has been deleted. The deletion will need to be reviewed by a moderator.' => 'Այս մեդիա օբյեկտը ջնջվել է: Ջնջումը պետք է վերանայվի մոդերատորի կողմից:',
  'This media object has been edited. You should review the changes and then %1$s or %2$s them.' => 'Այս մեդիա օբյեկտը խմբագրվել է: Դուք պետք է վերանայեք փոփոխությունները, այնուհետև %1$s կամ %2$s դրանք:',
  'This media object has been edited. The changes need to be reviewed by a moderator.' => 'Այս մեդիա օբյեկտը խմբագրվել է: Փոփոխությունները պետք է վերանայվեն մոդերատորի կողմից:',
  'A URL' => 'A URL',
  'Folder' => 'Թղթապանակ',
  'Same as uploaded file' => 'Նույնը, ինչ վերբեռնված ֆայլը',
  'If you have a large number of media files, you can organize them into folders and subfolders.' => 'Եթե դուք ունեք մեծ թվով մեդիա ֆայլեր, կարող եք դրանք կազմակերպել թղթապանակների և ենթաթղթապանակների մեջ:',
  'Create a unique filename' => 'Ստեղծեք եզակի ֆայլի անուն',
  'Keep open' => 'Բաց պահեք',
  'Census date and place' => 'Մարդահամարի ամսաթիվը և վայրը',
  'Generations' => 'Սերունդներ',
  'Layout' => 'Դասավորություն',
  'Sosa-Stradonitz number' => 'Սոսա-Ստրադոնից համարը',
  'API key' => 'API բանալի',
  'To use this service, you need an API key.' => 'Այս ծառայությունից օգտվելու համար ձեզ հարկավոր է API բանալի:',
  'Site verification code' => 'Կայքի հաստատման կոդը',
  'Site verification codes do not work when webtrees is installed in a subfolder.' => 'Կայքի ստուգման կոդերը չեն աշխատում, երբ վեբ ծառերը տեղադրվում են ենթաթղթապանակում:',
  'Create a shared note using the census assistant' => 'Ստեղծեք ընդհանուր նշում՝ օգտագործելով մարդահամարի օգնականը',
  'Citation' => 'Մեջբերում',
  'Census transcript' => 'Մարդահամարի արձանագրություն',
  'Household' => 'Տնային տնտեսություն',
  'Chart type' => 'Գծապատկերի տեսակը',
  'The clippings cart allows you to take extracts from this family tree and download them as a GEDCOM file.' => 'Հատվածների զամբյուղը թույլ է տալիս քաղվածքներ վերցնել այս տոհմածառից և ներբեռնել դրանք որպես GEDCOM ֆայլ:',
  'Your clippings cart is empty.' => 'Ձեր հատվածների զամբյուղը դատարկ է:',
  'Add content to the end of the <code>&lt;head&gt;</code> element.' => 'Բովանդակություն ավելացրեք <code>&lt;head&gt;</code> տարրի վերջում:',
  'Include the <code>&lt;style&gt;&lt;/style&gt;</code> tags.' => 'Ներառեք <code>&lt;style&gt;&lt;/style&gt;</code> թեգերը:',
  'Add content to the end of the <code>&lt;body&gt;</code> element.' => 'Ավելացրեք բովանդակություն <code>&lt;body&gt;</code> տարրի վերջում:',
  'Include the <code>&lt;script&gt;&lt;/script&gt;</code> tags.' => 'Ներառեք <code>&lt;script&gt;&lt;/script&gt;</code> թեգերը:',
  'd’Aboville number' => 'համարը դ’Աբովիլից հետո',
  'Family of %s' => '%s-ի ընտանիք',
  'Descendant generations' => 'Հետնորդ սերունդներ',
  'Show spouses' => 'Ցույց տալ ամուսիններին',
  'Zoom' => 'Մեծացնել',
  'FAQs are lists of questions and answers, which allow you to explain the site’s rules, policies, and procedures to your visitors. Questions are typically concerned with privacy, copyright, user-accounts, unsuitable content, requirement for source-citations, etc.' => 'ՀՏՀ-ները հարցերի և պատասխանների ցուցակներ են, որոնք թույլ են տալիս ձեր այցելուներին բացատրել կայքի կանոնները, քաղաքականությունը և ընթացակարգերը: Հարցերը սովորաբար վերաբերում են գաղտնիությանը, հեղինակային իրավունքին, օգտատերերի հաշիվներին, ոչ պիտանի բովանդակությանը, աղբյուրի մեջբերումների պահանջներին և այլն:',
  'You may use HTML to format the answer and to add links to other websites.' => 'Պատասխանը ձևաչափելու և այլ կայքերին հղումներ ավելացնելու համար կարող եք օգտագործել HTML:',
  'Sort order' => 'Տեսակավորելու կարգը',
  'Question' => 'Հարց',
  'Answer' => 'Պատասխանել',
  'Show this block for which languages' => 'Ցույց տալ այս բլոկը, թե որ լեզուների համար',
  'An FAQ can be displayed on just one of the family trees, or on all the family trees.' => 'ՀՏՀ-ն կարող է ցուցադրվել տոհմածառերից միայն մեկի կամ բոլոր տոհմածառերի վրա:',
  'back to top' => 'վերադառնալ դեպի վերև',
  'Are you sure you want to remove this item from your list of favorites?' => 'Իսկապե՞ս ուզում եք հեռացնել այս տարրը ձեր ընտրյալների ցանկից?',
  'Add a favorite' => 'Ավելացնել ֆավորիտ',
  'Enter an optional note about this favorite' => 'Մուտքագրեք կամընտիր նշում այս սիրելիի մասին',
  'Surname option' => 'Ազգանուն տարբերակ',
  'Convert to' => 'Փոխարկել',
  'Replace' => 'Փոխարինել',
  'Search text/pattern' => 'Որոնել տեքստ/օրինաչափություն',
  'Replacement text' => 'Փոխարինող տեքստ',
  'Search method' => 'Որոնման մեթոդ',
  'Regular expressions are an advanced pattern matching technique.' => 'Կանոնավոր արտահայտությունները օրինաչափությունների համապատասխանեցման առաջադեմ տեխնիկա են:',
  'Match both upper and lower case letters.' => 'Համապատասխանեցրեք և՛ մեծ, և՛ փոքրատառ տառերը:',
  'Records' => 'Գրառումներ',
  'Content' => 'Բովանդակություն',
  'No news articles have been submitted.' => 'Լրատվական հոդվածներ չեն ներկայացվել։',
  'Add a news article' => 'Ավելացնել նորությունների հոդված',
  'Show date of last update' => 'Ցույց տալ վերջին թարմացման ամսաթիվը',
  'Total surnames' => 'Ընդհանուր ազգանուններ',
  'Total events' => 'Ընդհանուր իրադարձություններ',
  'Total users' => 'Ընդհանուր օգտվողներ',
  'Earliest birth' => 'Ամենավաղ ծնունդը',
  'Latest birth' => 'Վերջին ծնունդը',
  'Earliest death' => 'Ամենավաղ մահը',
  'Latest death' => 'Վերջին մահը',
  'Individual who lived the longest' => 'Անհատ, ով ամենաերկարն է ապրել',
  'Family with the most children' => 'Ամենաշատ երեխա ունեցող ընտանիք',
  'Most common surnames' => 'Ամենատարածված ազգանունները',
  'Number of surnames' => 'Ազգանունների թիվը',
  'This family tree was last updated on %s.' => 'Այս տոհմածառը վերջին անգամ թարմացվել է %s -ին:',
  'To use this service, you need an account.' => 'Այս ծառայությունից օգտվելու համար ձեզ հարկավոր է հաշիվ:',
  'Templates' => 'Կաղապարներ',
  'To assist you in getting started with this block, we have created several standard templates. When you select one of these templates, the text area will contain a copy that you can then alter to suit your site’s requirements.' => 'Որպեսզի օգնենք ձեզ սկսել այս բլոկը, մենք ստեղծել ենք մի քանի ստանդարտ ձևանմուշներ: Երբ ընտրեք այս ձևանմուշներից մեկը, տեքստի տարածքը կպարունակի պատճեն, որը կարող եք այնուհետև փոփոխել՝ ձեր կայքի պահանջներին համապատասխան:',
  'As well as using the toolbar to apply HTML formatting, you can insert database fields which are updated automatically. These special fields are marked with <b>#</b> characters. For example <b>#totalFamilies#</b> will be replaced with the actual number of families in the database. Advanced users may wish to apply CSS classes to their text, so that the formatting matches the currently selected theme.' => 'Ինչպես նաև HTML ձևաչափումը կիրառելու համար գործիքագոտին օգտագործելով, կարող եք տեղադրել տվյալների բազայի դաշտերը, որոնք ինքնաբերաբար թարմացվում են: Այս հատուկ դաշտերը նշված են <b>#</b> նիշերով: Օրինակ, <b>#totalFamilies#</b>-ը կփոխարինվի տվյալների բազայի ընտանիքների իրական թվով: Ընդլայնված օգտվողները կարող են ցանկանալ կիրառել CSS դասեր իրենց տեքստում, որպեսզի ձևաչափումը համապատասխանի տվյալ պահին ընտրված թեմային:',
  'Show the date and time of update' => 'Ցույց տալ թարմացման ամսաթիվը և ժամը',
  'This family tree was last updated on #gedcomUpdated#. There are #totalSurnames# surnames in this family tree. The earliest recorded event is the #firstEventType# of #firstEventName# in #firstEventYear#. The most recent event is the #lastEventType# of #lastEventName# in #lastEventYear#.<br><br>If you have any comments or feedback please contact #contactWebmaster#.' => 'Այս տոհմածառը վերջին անգամ թարմացվել է #gedcomUpdated#-ին: Այս տոհմածառում կան #ընդհանուրԱզգանուններ# ազգանուններ։ Ամենավաղ գրանցված իրադարձությունը #firstEventType#-ի #firstEventName#-ն է #firstEventYear#-ում: Ամենավերջին իրադարձությունը #lastEventName#-ի #lastEventType#-ն է #lastEventYear#-ում:<br><br>Եթե ունեք մեկնաբանություն կամ կարծիք, դիմեք #contactWebmaster#:',
  'Use compact layout' => 'Օգտագործեք կոմպակտ դասավորություն',
  'Add individuals' => 'Ավելացնել անհատներ',
  'Include the individual’s immediate family' => 'Ներառեք անհատի անմիջական ընտանիքը',
  'Select individuals by place or date' => 'Ընտրեք անհատներին ըստ վայրի կամ ամսաթվի',
  'Start year' => 'Մեկնարկային տարի',
  'End year' => 'Ավարտական տարի',
  'You are signed in as %s.' => 'Դուք մուտք եք գործել որպես %s:',
  'sign out' => 'դուրս գալ',
  'Media objects per page' => 'Մեդիա օբյեկտներ մեկ էջի համար',
  'Search filters' => 'Որոնման զտիչներ',
  'Media objects found' => 'Հայտնաբերվել են լրատվամիջոցների օբյեկտներ',
  'Page %s of %s' => '%s էջ %s -ից',
  'Show all media' => 'Ցուցադրել բոլոր լրատվամիջոցները',
  'There are no media objects for this individual.' => 'Այս անհատի համար լրատվամիջոցների օբյեկտներ չկան։',
  'Show all notes' => 'Ցույց տալ բոլոր նշումները',
  'There are no notes for this individual.' => 'Այս անձի համար նշումներ չկան:',
  'Add a note' => 'Ավելացնել նշում',
  'Siblings' => 'Եղբայրներ և եղբայրներ',
  'Sibling' => 'Եղբայր կամ եղբայր',
  'Nothing to show' => 'Ցույց տալու ոչինչ չկա',
  'Associated events' => 'Առնչվող իրադարձություններ',
  'Events of close relatives' => 'Մերձավոր ազգականների իրադարձություններ',
  'There are no facts for this individual.' => 'Այս անձի համար փաստեր չկան:',
  'No results found.' => 'Ոչ մի արդյունք չի գտնվել:',
  'Place list' => 'Տեղերի ցուցակ',
  'View table of events occurring in %s' => 'Դիտեք %s-ում տեղի ունեցող իրադարձությունների աղյուսակը',
  'The location of this place is not known.' => 'Այս վայրի գտնվելու վայրը հայտնի չէ։',
  'This website uses cookies to learn about visitor behavior.' => 'Այս կայքը օգտագործում է թխուկներ՝ ծանոթանալու այցելուների վարքագծին:',
  'Personal data' => 'Անձնական տվյալներ',
  'This website processes personal data for the purpose of historical and genealogical research.' => 'Այս կայքը մշակում է անձնական տվյալները՝ պատմական և ծագումնաբանական հետազոտությունների նպատակով:',
  'This research is a “legitimate interest” under article 6(f) of the EU General Data Protection Regulations.' => 'Այս հետազոտությունը հանդիսանում է «օրինական շահ»՝ համաձայն ԵՄ տվյալների պաշտպանության ընդհանուր կանոնակարգի 6-րդ հոդվածի «զ»:',
  'Cookies' => 'Թխվածքաբլիթներ',
  'This website uses cookies to enable login sessions, and to remember preferences such as your chosen language.' => 'Այս կայքը օգտագործում է թխուկներ՝ մուտք գործելու նիստերը միացնելու և ձեր ընտրած լեզուն հիշելու համար:',
  'These cookies are “essential”, and do not require consent.' => 'Այս թխուկները «էական» են և համաձայնություն չեն պահանջում:',
  'This website uses third-party services to learn about visitor behavior.' => 'Այս կայքը օգտագործում է երրորդ կողմի ծառայություններ՝ այցելուների վարքագծի մասին իմանալու համար:',
  'These services may use cookies or other tracking technology.' => 'Այս ծառայությունները կարող են օգտագործել թխուկներ կամ հետագծման այլ տեխնոլոգիա:',
  'You can opt out of tracking by setting the “Do Not Track” header in your browser preferences.' => 'Դուք կարող եք հրաժարվել հետևելուց՝ ձեր դիտարկիչի նախապատվություններում դնելով «Չհետևել» վերնագիրը:',
  'Data controller' => 'Տվյալների վերահսկիչ',
  'This website is operated by the following individuals.' => 'Այս կայքը շահագործվում է հետևյալ անձանց կողմից.',
  'Show only individuals, events, or all' => 'Ցույց տալ միայն անհատներին, իրադարձություններին կամ բոլորին',
  'Show slide show controls' => 'Ցուցադրել սլայդերի ցուցադրման հսկիչները',
  'Start slide show on page load' => 'Սկսեք սլայդերի ցուցադրումը էջի բեռնման ժամանակ',
  'Next image' => 'Հաջորդ պատկերը',
  'Changed on %1$s by %2$s' => 'Փոխվել է %1$s -ում %2$s -ով',
  'Changed on %1$s' => 'Փոխվել է %1$s -ին',
  'Changed by %1$s' => 'Փոխվել է %1$s -ով',
  'Number of days to show' => 'Ցույց տալու օրերի քանակը',
  'maximum %s day' . "\0" . 'maximum %s days' => 'առավելագույնը %s օր' . "\0" . 'առավելագույնը %s օրեր',
  'Show the user who made the change' => 'Ցույց տալ օգտվողին, ով կատարել է փոփոխությունը',
  'Show the date and time' => 'Ցույց տալ ամսաթիվը և ժամը',
  'Searching for all possible relationships can take a lot of time in complex trees.' => 'Բոլոր հնարավոր հարաբերությունների որոնումը կարող է շատ ժամանակ խլել բարդ ծառերի մեջ:',
  'How much recursion to use when searching for relationships' => 'Որքա՞ն ռեկուրսիա օգտագործել հարաբերություններ որոնելիս',
  'Individual 1' => 'Անհատական 1',
  'Individual 2' => 'Անհատական 2',
  'Swap individuals' => 'Փոխանակում անհատներին',
  'Add marriage details' => 'Ավելացնել ամուսնության մանրամասները',
  'Add a brother' => 'Ավելացնել եղբայր',
  'Add a sister' => 'Ավելացրեք քույր',
  'Add a sibling' => 'Ավելացրեք քույր կամ եղբայր',
  'Date differences' => 'Ամսաթվերի տարբերություններ',
  'This block will show editors a list of records with pending changes that need to be reviewed by a moderator. It also generates daily emails to moderators whenever pending changes exist.' => 'Այս բլոկը խմբագիրներին ցույց կտա սպասվող փոփոխություններով գրառումների ցանկ, որոնք պետք է վերանայվեն մոդերատորի կողմից: Այն նաև ստեղծում է ամենօրյա նամակներ մոդերատորներին, երբ առկա են սպասվող փոփոխություններ:',
  'Send out reminder emails' => 'Ուղարկեք հիշեցման նամակներ',
  'Reminder email frequency (days)' => 'Հիշեցման էլփոստի հաճախականությունը (օր)',
  'The URL was copied to the clipboard' => 'URL-ը պատճենվել է clipboard-ում',
  'Sitemaps are a way for webmasters to tell search engines about the pages on a website that are available for crawling. All major search engines support sitemaps. For more information, see <a href="https://www.sitemaps.org/">www.sitemaps.org</a>.' => 'Կայքի քարտեզները վեբ վարպետների համար որոնման համակարգերին պատմելու միջոց են կայքի այն էջերի մասին, որոնք հասանելի են սողալու համար: Բոլոր հիմնական որոնման համակարգերը աջակցում են կայքի քարտեզներին: Լրացուցիչ տեղեկությունների համար տես <a href="https://www.sitemaps.org/">www.sitemaps.org</a>:',
  'Which family trees should be included in the sitemaps' => 'Որ տոհմածառերը պետք է ներառվեն կայքի քարտեզներում',
  'Show all sources' => 'Ցույց տալ բոլոր աղբյուրները',
  'There are no source citations for this individual.' => 'Այս անձի համար աղբյուրների մեջբերումներ չկան:',
