  'Remove individual' => 'Հեռացնել անհատը',
  'Show an age cursor' => 'Ցույց տալ տարիքային կուրսորը',
  'Show only events of living individuals' => 'Ցույց տալ միայն կենդանի անհատների իրադարձությունները',
  'Research tasks are special events, added to individuals in your family tree, which identify the need for further research. You can use them as a reminder to check facts against more reliable sources, to obtain documents or photographs, to resolve conflicting information, etc.' => 'Հետազոտական առաջադրանքները հատուկ իրադարձություններ են, որոնք ավելացվում են ձեր տոհմածառի անհատներին, որոնք բացահայտում են հետագա հետազոտությունների անհրաժեշտությունը: Դուք կարող եք դրանք օգտագործել որպես հիշեցում՝ փաստերը ավելի վստահելի աղբյուրներից ստուգելու, փաստաթղթեր կամ լուսանկարներ ձեռք բերելու, հակասական տեղեկություններ լուծելու համար և այլն:',
  'To create new research tasks, you must first add “research task” to the list of facts and events in the family tree’s preferences.' => 'Նոր հետազոտական առաջադրանքներ ստեղծելու համար նախ պետք է «հետազոտական առաջադրանք» ավելացնել տոհմածառի նախապատվությունների փաստերի և իրադարձությունների ցանկին:',
  'Research tasks are stored using the custom GEDCOM tag “_TODO”. Other genealogy applications may not recognize this tag.' => 'Հետազոտական առաջադրանքները պահվում են՝ օգտագործելով «_TODO» հատուկ GEDCOM պիտակը: Այլ ծագումնաբանական հավելվածները կարող են չճանաչել այս պիտակը:',
  'Show research tasks that are assigned to other users' => 'Ցույց տալ հետազոտական առաջադրանքները, որոնք հանձնարարված են այլ օգտվողների',
  'Show research tasks that are not assigned to any user' => 'Ցույց տալ հետազոտական առաջադրանքները, որոնք հանձնարարված չեն որևէ օգտվողի',
  'Show research tasks that have a date in the future' => 'Ցույց տալ հետազոտական առաջադրանքները, որոնք ունեն ապագա ամսաթիվ',
  'Number of given names' => 'Տրված անունների թիվը',
  'Number of pages' => 'Էջերի քանակը',
  'Date sent' => 'Ուղարկելու ամսաթիվը',
  'RE: ' => 'RE: ',
  'Reply' => 'Պատասխանել',
  'Are you sure you want to delete this message? It cannot be retrieved later.' => 'Իսկապե՞ս ուզում եք ջնջել այս հաղորդագրությունը: Այն չի կարող ետ կանչվել:',
  'Delete selected messages' => 'Ջնջել ընտրված հաղորդագրությունները',
  'Add a journal entry' => 'Ավելացնել ամսագրի գրառում',
  'This note has been deleted. You should review the deletion and then %1$s or %2$s it.' => 'Այս նշումը ջնջվել է։ Դուք պետք է վերանայեք ջնջումը, այնուհետև %1$s կամ %2$s այն:',
  'This note has been deleted. The deletion will need to be reviewed by a moderator.' => 'Այս նշումը ջնջվել է։ Ջնջումը պետք է վերանայվի մոդերատորի կողմից:',
  'This note has been edited. You should review the changes and then %1$s or %2$s them.' => 'Այս նշումը խմբագրվել է։ Դուք պետք է վերանայեք փոփոխությունները, այնուհետև %1$s կամ %2$s դրանք:',
  'This note has been edited. The changes need to be reviewed by a moderator.' => 'Այս նշումը խմբագրվել է։ Փոփոխությունները պետք է վերանայվեն մոդերատորի կողմից:',
  'Accept' => 'Ընդունել',
  'Reject' => 'Մերժել',
  'Accept all changes' => 'Ընդունեք բոլոր փոփոխությունները',
  'Are you sure you want to reject all the changes to this family tree?' => 'Իսկապե՞ս ուզում եք մերժել այս տոհմածառի բոլոր փոփոխությունները?',
  'Reject all changes' => 'Մերժել բոլոր փոփոխությունները',
  'Add from clipboard' => 'Ավելացնել սեղմատախտակից',
  'Empty the clipboard' => 'Դատարկեք clipboard-ը',
  'This record has been deleted. You should review the deletion and then %1$s or %2$s it.' => 'Այս գրառումը ջնջվել է։ Դուք պետք է վերանայեք ջնջումը, այնուհետև %1$s կամ %2$s այն:',
  'This record has been deleted. The deletion will need to be reviewed by a moderator.' => 'Այս գրառումը ջնջվել է։ Ջնջումը պետք է վերանայվի մոդերատորի կողմից:',
  'This record has been edited. You should review the changes and then %1$s or %2$s them.' => 'Այս գրառումը խմբագրվել է։ Դուք պետք է վերանայեք փոփոխությունները, այնուհետև %1$s կամ %2$s դրանք:',
  'This record has been edited. The changes need to be reviewed by a moderator.' => 'Այս գրառումը խմբագրվել է։ Փոփոխությունները պետք է վերանայվեն մոդերատորի կողմից:',
  '<p>Notice: By completing and submitting this form, you agree:</p><ul><li>to protect the privacy of living individuals listed on our site;</li><li>and in the text box below, to explain to whom you are related, or to provide us with information on someone who should be listed on our website.</li></ul>' => '<p>Ծանուցում․ լրացնելով և ներկայացնելով այս ձևը՝ դուք համաձայնում եք՝</p><ul><li>պաշտպանել մեր կայքում թվարկված կենդանի անհատների գաղտնիությունը,</li><li>և ստորև բերված տեքստային վանդակում բացատրել, թե ում հետ եք դուք ազգակցական, կամ տրամադրել մեզ տեղեկություններ այն անձի մասին, ով պետք է նշված լինի մեր կայքում։</li></ul>',
  'Explain why you are requesting an account.' => 'Բացատրեք, թե ինչու եք հաշիվ պահանջում:',
  'Use this field to tell the site administrator why you are requesting an account and how you are related to the genealogy displayed on this site. You can also use this to enter any other comments you may have for the site administrator.' => 'Օգտագործեք այս դաշտը՝ կայքի ադմինիստրատորին հայտնելու համար, թե ինչու եք հաշիվ պահանջում և ինչպես եք կապված այս կայքում ցուցադրված ծագումնաբանության հետ: Դուք կարող եք նաև օգտագործել սա՝ կայքի ադմինիստրատորի համար ցանկացած այլ մեկնաբանություն մուտքագրելու համար:',
  'Hello %s…<br>Thank you for your registration.' => 'Բարև %s…<br>Շնորհակալություն գրանցման համար:',
  'We will now send a confirmation email to the address <b>%s</b>. You must verify your account request by following instructions in the confirmation email. If you do not confirm your account request within seven days, your application will be rejected automatically. You will have to apply again.<br><br>After you have followed the instructions in the confirmation email, the administrator still has to approve your request before your account can be used.<br><br>To sign in to this website, you will need to know your username and password.' => 'Այժմ մենք հաստատման նամակ կուղարկենք <b>%s</b> հասցեին: Դուք պետք է հաստատեք ձեր հաշվի հարցումը՝ հետևելով հաստատման էլ. Եթե յոթ օրվա ընթացքում չհաստատեք ձեր հաշվի հարցումը, ձեր դիմումն ինքնաբերաբար կմերժվի: Դուք պետք է նորից դիմեք:<br><br>Հաստատման նամակում տրված հրահանգներին հետևելուց հետո ադմինիստրատորը դեռ պետք է հաստատի ձեր հարցումը, նախքան ձեր հաշիվն օգտագործելը:<br><br>Այս կայք մուտք գործելու համար դուք պետք է իմանաք ձեր օգտանունը և գաղտնաբառը:',
  'Add more fields' => 'Ավելացնել ավելի շատ դաշտեր',
  'Father' => 'Հայրիկ',
  'Mother' => 'Մայրիկ',
  'Search for' => 'Որոնել',
  'Phonetic algorithm' => 'Հնչյունական ալգորիթմ',
  'Replace with' => 'Փոխարինել հետ',
  'Entire record' => 'Ամբողջ ռեկորդը',
  'replace' => 'փոխարինել',
  'select all' => 'ընտրել բոլորը',
  'select none' => 'ընտրել ոչ մեկը',
  'invert selection' => 'շրջել ընտրությունը',
  'Checking server configuration' => 'Սերվերի կոնֆիգուրացիայի ստուգում',
  'The server configuration is OK.' => 'Սերվերի կոնֆիգուրացիան կարգին է:',
  'Checking server capacity' => 'Սերվերի հզորության ստուգում',
  'The memory and CPU time requirements depend on the number of individuals in your family tree.' => 'Հիշողության և պրոցեսորի ժամանակի պահանջները կախված են ձեր տոհմածառի անհատների թվից:',
  'The following list shows typical requirements.' => 'Հետևյալ ցանկը ցույց է տալիս բնորոշ պահանջները:',
  'Small systems (500 individuals): 16–32 MB, 10–20 seconds' => 'Փոքր համակարգեր (500 անհատներ)՝ 16–32 ՄԲ, 10–20 վայրկյան',
  'Medium systems (5,000 individuals): 32–64 MB, 20–40 seconds' => 'Միջին համակարգեր (5000 անհատներ)՝ 32–64 ՄԲ, 20–40 վայրկյան',
  'Large systems (50,000 individuals): 64–128 MB, 40–80 seconds' => 'Խոշոր համակարգեր (50,000 անհատներ)՝ 64–128 ՄԲ, 40–80 վայրկյան',
  'This server’s memory limit is %s MB and its CPU time limit is %s seconds.' => 'Այս սերվերի հիշողության սահմանաչափը %s ՄԲ է, իսկ պրոցեսորի ժամանակը` %s վայրկյան:',
  'If you try to exceed these limits, you may experience server time-outs and blank pages.' => 'Եթե փորձեք գերազանցել այս սահմանները, դուք կարող եք հանդիպել սերվերի ժամանակի դադարեցման և դատարկ էջերի հետ:',
  'Connection to database server' => 'Միացում տվյալների բազայի սերվերին',
  'webtrees needs a database to store your genealogy data.' => 'webtrees-ին անհրաժեշտ է տվյալների բազա՝ ձեր ծագումնաբանական տվյալները պահելու համար:',
  'Database type' => 'Տվյալների բազայի տեսակը',
  'Database connection' => 'Տվյալների բազայի միացում',
  'Connection type' => 'Միացման տեսակը',
  'network' => 'ցանց',
  'Table prefix' => 'Սեղանի նախածանց',
  'The prefix is optional, but recommended. By giving the table names a unique prefix you can let several different applications share the same database.' => 'Նախածանցը ընտրովի է, բայց խորհուրդ է տրվում: Աղյուսակների անունները տալով եզակի նախածանց՝ կարող եք թույլ տալ, որ մի քանի տարբեր հավելվածներ կիսեն նույն տվյալների բազան:',
  'Use letters A-Z, a-z, digits 0-9, or underscores' => 'Օգտագործեք A-Z, a-z տառերը, 0-9 թվանշանները կամ ընդգծումները',
  'Most sites are configured to use localhost. This means that your database runs on the same computer as your web server.' => 'Կայքերի մեծ մասը կազմաձևված է տեղական հոսթ օգտագործելու համար: Սա նշանակում է, որ ձեր տվյալների բազան աշխատում է նույն համակարգչով, ինչ ձեր վեբ սերվերը:',
  'Most sites are configured to use the default value of 5432.' => 'Կայքերի մեծ մասը կազմաձևված է օգտագործել 5432-ի լռելյայն արժեքը:',
  'Most sites are configured to use the default value of 1433.' => 'Կայքերի մեծ մասը կազմաձևված է օգտագործել 1433-ի լռելյայն արժեքը:',
  'Administrator account' => 'Ադմինիստրատորի հաշիվ',
  'You need to set up an administrator account. This account can control all aspects of this webtrees installation. Please choose a strong password.' => 'Դուք պետք է ստեղծեք ադմինիստրատորի հաշիվ: Այս հաշիվը կարող է վերահսկել այս webtrees-ի տեղադրման բոլոր ասպեկտները: Խնդրում ենք ընտրել ուժեղ գաղտնաբառ:',
  'You will use this to sign in to webtrees.' => 'Դուք կօգտագործեք սա վեբ ծառեր մուտք գործելու համար:',
  'This must be at least six characters long. It is case-sensitive.' => 'Սա պետք է լինի առնվազն վեց նիշ: Այն զգայուն է մեծատառերի նկատմամբ:',
  '%s grandchild' . "\0" . '%s grandchildren' => '%s թոռ' . "\0" . '%s թոռներ',
  'Could not verify the information you entered. Please try again or contact the site administrator for more information.' => 'Չհաջողվեց հաստատել ձեր մուտքագրած տեղեկատվությունը: Խնդրում ենք կրկին փորձել կամ կապվել կայքի ադմինիստրատորի հետ լրացուցիչ տեղեկությունների համար:',
  'You have confirmed your request to become a registered user.' => 'Դուք հաստատել եք գրանցված օգտվող դառնալու Ձեր հայտը:',
  'The administrator has been informed. As soon as they give you permission to sign in, you can sign in with your username and password.' => 'Ադմինիստրատորը տեղեկացված է. Հենց որ նրանք ձեզ մուտք գործելու թույլտվություն տան, կարող եք մուտք գործել ձեր օգտանունով և գաղտնաբառով:',
  'Show sources' => 'Ցույց տալ աղբյուրները',
  'Show notes' => 'Ցույց տալ նշումները',
  'Show occupations' => 'Ցույց տալ զբաղմունքները',
  'Show residences' => 'Ցույց տալ բնակավայրերը',
  'Show children of ancestors' => 'Ցույց տվեք նախնիների երեխաներին',
  'paper sizeA4' => 'A4',
