  'A report of facts which are supported by a given source.' => 'Փաստերի հաշվետվություն, որը հաստատվում է տվյալ աղբյուրով:',
  'Find a source' => 'Գտեք աղբյուր',
  'Source type' => 'Աղբյուրի տեսակը',
  'Show photos' => 'Ցույց տալ լուսանկարներ',
